// Books: a reader for the EPUB books on the frame's card, and a shop of free
// ones. The library lists every .epub below the scene's folder (the whole
// card by default) with its cover and how far you are, the book you read last
// first; a book opens where you left it.
//
// In a book: pages that fit the screen (text size, spacing, margins, justified
// or not, a light, sepia or dark page on a screen), its pictures, contents,
// bookmarks, highlights with notes (a long press on a word, or "Highlight a
// passage" with the keys), find in the book, go to any place, and how long
// the chapter and the book have left at your own pace. The library's
// download button opens the catalogs: Project Gutenberg, Standard Ebooks'
// newest, and any OPDS catalog the `catalogs` field lists. The chart button
// is your reading: today, the week, the streak, your pace; and there the
// notes export (Markdown, a Kindle "My Clippings.txt", a backup) and import.
//
// What is where (docs in each file): epub.ts reads books, pages.ts lays them
// out, reader.tsx draws a book, views.tsx the pages around it, marks.ts keeps
// the marks and writes the exports, stats.ts counts the reading, catalog.ts
// finds and downloads books, ui.tsx is what they share.
//
// State: `spot` (private, on disk) is where you are: the view, the book and
// the place in it, the starts of the pages read so far in the chapter, every
// book's place and reading time, the reading settings. `marks` (private, on
// disk) holds the bookmarks, highlights and notes. A book handed over by
// another scene (the Files app, through `settings.opens`) comes in `file`.
//
// Keys: in a book Next / Prev turn pages, Action opens the book's menu, Back
// goes a page back (Escape: the library). In a list Next / Prev move, Action
// opens. Pages with buttons (a book's page in a catalog, the stats) are
// walked by the frame's own keys ring.

import { Z, px, ROUND, uiOf, I, Btn, listRoom, paginate, pageOf, duration, ago, sizeText } from './ui'
import { placeOf, keyOf, normalKey, bookName, storagesOf, openBook, chapterOf, readPackage, picturesFor } from './epub'
import { prefsOf, geometry, turn, spreadOf, jumpTo, shareOf, placeAt, charsLeft, charsBefore } from './pages'
import { readMarks, saveMarks, listOf, putMark, dropMark, findMark, bookmarkOn, textBetween, newId, cut, MAX_TEXT, toMarkdown, toClippings, toBackup, mergeBackup, fileName, BACKUP_NAME, CLIPPINGS_NAME } from './marks'
import { countTurn, readingSpeed, summary } from './stats'
import { SHELVES, SE_FEED, feedsOf, hostOf, load, gutendexUrl, fromGutendex, parseAtom, searchTemplate, bookFile, startDownload, stepDownload } from './catalog'
import { Reader, normal } from './reader'
import { LibraryView, ListPage, MarkView, NoteView, AskView, StatsView, EntryView, thousands } from './views'

const LIST_MS = 5 * 60 * 1000
const BOOKS_KEPT = 60
const VIEWS = ['library', 'book', 'menu', 'contents', 'mark', 'note', 'find', 'stats', 'catalog', 'shelves', 'feed', 'entry', 'search', 'link']
const BOOK_VIEWS = ['book', 'menu', 'contents', 'mark', 'note', 'find']
// Views whose buttons the frame's keys ring walks, and views with a field to
// type in: the app keeps no key there.
const RING_VIEWS = ['mark', 'note', 'stats', 'entry', 'search', 'link']
const TYPING_VIEWS = ['note', 'search', 'link', 'find']

// What lives only as long as the interpreter.
let listed = { folder: null, at: 0, books: [] }
const metas = new Map() // path -> { title, author, cover } | { error }
const drafts = {} // view -> the text being typed
let touchedAt = 0 // when a handler last ran: a render answering it does no slow work

function readJson(value) {
  let v = value
  if (typeof v === 'string') {
    try {
      v = JSON.parse(v)
    } catch (e) {
      v = null
    }
  }
  return v && typeof v === 'object' && !Array.isArray(v) ? v : {}
}

const readSpot = (app) => readJson(app.state.spot)
const saveSpot = (spot) => frameos.setState('spot', spot)

// ---- The library's books ----------------------------------------------------------

// Every .epub below the folder, in every storage the frame has, as keys.
function booksIn(folder, storages, fresh) {
  const where = `${folder}|${storages.map((s) => s.id).join(',')}`
  const kept = fresh ? null : frameos.recall('library')
  if (!fresh && listed.folder === where && Date.now() - listed.at < LIST_MS) return listed.books
  if (kept && typeof kept === 'object' && kept.folder === where && Date.now() - kept.at < LIST_MS && Array.isArray(kept.books)) {
    listed = kept
    return listed.books
  }
  const books = []
  for (const storage of storages) {
    for (const path of frameos.listAssets(folder, { storage: storage.id }) || []) {
      if (/\.epub$/i.test(path) && !/(^|\/)\._/.test(path)) books.push(keyOf(storage.id, path))
    }
  }
  listed = { folder: where, at: Date.now(), books }
  frameos.remember('library', listed)
  return books
}

function forgetListing() {
  listed = { folder: null, at: 0, books: [] }
  frameos.remember('library', null)
}

// A book's title, author and cover, read from its package once and kept in
// the spot (`shelf`): on an ESP32's flash a package costs seconds to read, and
// a frame that sleeps would read every one again at each wake.
function metaOf(path, spot) {
  if (metas.has(path)) return metas.get(path)
  const shelf = spot.shelf && typeof spot.shelf === 'object' ? spot.shelf : (spot.shelf = {})
  let meta = shelf[path]
  if (!meta || typeof meta !== 'object' || typeof meta.title !== 'string') {
    const pkg = readPackage(path)
    meta = pkg.error ? { title: bookName(path), author: '', error: pkg.error } : { title: pkg.title, author: pkg.author, cover: pkg.cover || null }
    shelf[path] = meta
  }
  metas.set(path, meta)
  return meta
}

// Opens a book where it was left, or at its first page with text.
function openAt(spot, path, ui) {
  const book = openBook(path)
  if (book.error) return book
  const kept = spot.books && spot.books[path]
  const at = kept && typeof kept.s === 'number' && kept.s < book.spine.length ? { s: kept.s, p: kept.p || 0, b: kept.b || 0, c: kept.c || 0 } : { s: 0, p: 0, b: 0, c: 0 }
  if (chapterOf(book, at.s, at.p, ui).blocks.length === 0) {
    for (let s = at.s; s < book.spine.length; s++) {
      if (chapterOf(book, s, 0, ui).blocks.length > 0) {
        Object.assign(at, { s, p: 0, b: 0, c: 0 })
        break
      }
    }
  }
  spot.at = at
  spot.pg = null
  return book
}

// Where a book was left, for the library and the next open; the books read
// longest ago are forgotten first (their marks stay).
function keepPlace(spot, book, now, share, left) {
  const books = spot.books && typeof spot.books === 'object' ? spot.books : {}
  const was = books[book.path] || {}
  books[book.path] = {
    ...was,
    s: spot.at.s,
    p: spot.at.p,
    b: spot.at.b,
    c: spot.at.c,
    n: book.spine.length,
    t: now,
    title: book.title,
    author: book.author,
    cover: book.cover || null,
    f: share === undefined ? was.f || 0 : Math.round(share * 10000) / 10000,
    left: left === undefined ? was.left : Math.round(left),
  }
  const paths = Object.keys(books).sort((a, b) => (books[b].t || 0) - (books[a].t || 0))
  for (const path of paths.slice(BOOKS_KEPT)) delete books[path]
  spot.books = books
}

// ---- Sentences, for picking a passage with keys ------------------------------------

const SENTENCE = /[.!?…]+["'”’)\]]*\s+/g

function sentenceEnds(t) {
  const ends = []
  SENTENCE.lastIndex = 0
  let m
  while ((m = SENTENCE.exec(t))) ends.push(m.index + m[0].replace(/\s+$/, '').length)
  if (!ends.length || ends[ends.length - 1] < t.length) ends.push(t.length)
  return ends
}

function sentenceStarts(t) {
  const starts = [0]
  SENTENCE.lastIndex = 0
  let m
  while ((m = SENTENCE.exec(t))) if (m.index + m[0].length < t.length) starts.push(m.index + m[0].length)
  return starts
}

function stepStart(blocks, a, by) {
  let [b, c] = a
  const own = blocks[b] && blocks[b].t ? sentenceStarts(blocks[b].t) : []
  if (by > 0) {
    const next = own.find((x) => x > c)
    if (next !== undefined) return [b, next]
    for (let i = b + 1; i < blocks.length; i++) if (blocks[i].t) return [i, 0]
    return a
  }
  const prev = own.filter((x) => x < c).pop()
  if (prev !== undefined) return [b, prev]
  for (let i = b - 1; i >= 0; i--) if (blocks[i].t) return [i, sentenceStarts(blocks[i].t).pop()]
  return a
}

function stepEnd(blocks, z, a, by) {
  const [b, c] = z
  const own = blocks[b] && blocks[b].t ? sentenceEnds(blocks[b].t) : []
  if (by > 0) {
    const next = own.find((x) => x > c)
    if (next !== undefined) return [b, next]
    for (let i = b + 1; i < blocks.length; i++) if (blocks[i].t) return [i, sentenceEnds(blocks[i].t)[0]]
    return z
  }
  const prev = own.filter((x) => x < c && (b > a[0] || x > a[1])).pop()
  if (prev !== undefined) return [b, prev]
  for (let i = b - 1; i >= a[0]; i--) if (blocks[i].t) return [i, blocks[i].t.length]
  return z
}

// ---- Keys ------------------------------------------------------------------------------

export function onEvent(app, context) {
  const p = context.payload || {}
  const event = context.event
  const spot = readSpot(app)
  const view = VIEWS.includes(spot.view) ? spot.view : 'library'
  const sheet = view === 'book' && spot.sheet && !spot.selm
  let cmd = null
  if (event === 'button') {
    if (p.action !== 'press') return false
    const role = String(p.role || '').toLowerCase()
    if (sheet && role === 'back') {
      cmd = 'back'
    } else if (RING_VIEWS.includes(view) || TYPING_VIEWS.includes(view) || sheet) return false
    const label = String(p.label || '').toUpperCase()
    if (cmd) {
      // a sheet's Back, above
    } else if (role === 'next' || role === 'right' || role === 'down' || (!role && (label === 'DOWN' || label === 'RIGHT' || label === 'NEXT'))) cmd = 'next'
    else if (role === 'prev' || role === 'left' || role === 'up' || (!role && (label === 'UP' || label === 'LEFT' || label === 'PREV' || label === 'PREVIOUS'))) cmd = 'prev'
    else if (role === 'back') cmd = 'back'
    else cmd = 'select'
  } else if (event === 'keyDown') {
    if (p.ctrl || p.alt || p.meta) return false
    // Escape closes a sheet over the page; its buttons are the ring's.
    if (sheet && (p.key === 'Escape' || p.key === 'Backspace')) cmd = 'back'
    else if (RING_VIEWS.includes(view) || TYPING_VIEWS.includes(view) || sheet) return false
    const key = p.key
    if (cmd) {
      // a sheet's Escape, above
    } else if (key === 'ArrowRight' || key === 'ArrowDown' || key === 'PageDown' || key === ' ') cmd = 'next'
    else if (key === 'ArrowLeft' || key === 'ArrowUp' || key === 'PageUp') cmd = 'prev'
    else if (key === 'Enter') cmd = 'select'
    else if (key === 'Escape' || key === 'Backspace') cmd = 'back'
  } else if (event === 'forward') {
    if (view !== 'book' || sheet) return false
    cmd = 'next'
  } else if (event === 'back') {
    // In a book the frame's Back is the page before; elsewhere, the page
    // this one came from. The library is the first page: there it is the
    // frame's.
    if (view === 'library') return false
    cmd = view === 'book' && !sheet && !spot.selm ? 'prev' : 'back'
  }
  if (!cmd) return false
  // An empty library has only its buttons: the keys walk them and press them.
  if (spot.empty === true && (event === 'button' || event === 'keyDown') && view === 'library') return false
  spot.cmd = cmd
  spot.keys = true
  saveSpot(spot)
  return true
}

// ---- Drawing -----------------------------------------------------------------------------

export function get(app, context) {
  ROUND.canvas = null
  const out = draw(app, context)
  if (!ROUND.canvas) return out.ui
  const { width, height, side } = ROUND.canvas
  return (
    <div className={`relative w-[${width}px] h-[${height}px] ${out.sheet ? out.look.sheet : out.look.bg}`}>
      <div className={`absolute left-[${(width - side) >> 1}px] top-[${(height - side) >> 1}px] w-[${side}px] h-[${side}px]`}>{out.ui}</div>
    </div>
  )
}

function draw(app, context) {
  const spot = readSpot(app)
  const prefs = prefsOf(spot)
  spot.prefs = prefs
  delete spot.size
  const ui = uiOf(app, context, prefs)
  let marks = readMarks(app)
  const now = Date.now()
  const save = () => saveSpot(spot)
  const storages = storagesOf(app)
  // writeAsset and appendAsset reach the assets folder alone: a frame whose
  // only storage is its internal one (an ESP32 with no card) keeps no
  // downloads and no exports.
  const writable = storages.some((s) => s.id === 'assets')
  const NO_CARD = 'Downloads and exports need a TF card in this frame.'
  const folder = typeof app.state.folder === 'string' ? app.state.folder.trim().replace(/^\/+|\/+$/g, '') : ''
  // Where downloads and exported notes go: the books folder, else "Books".
  const home = folder || 'Books'
  const notesFolder = `${home}/Notes`
  const languages = typeof app.state.languages === 'string' ? app.state.languages.trim().replace(/\s+/g, '') : 'en'
  const feeds = feedsOf(app.state.catalogs)

  // Keys from before storages (bare paths) are the assets folder's.
  if (spot.book) spot.book = normalKey(spot.book, storages)
  for (const field of ['books', 'shelf']) {
    const map = spot[field]
    if (map && typeof map === 'object' && Object.keys(map).some((key) => normalKey(key, storages) !== key)) {
      const moved = {}
      for (const key of Object.keys(map)) moved[normalKey(key, storages)] = map[key]
      spot[field] = moved
    }
  }
  if (!spot.books || typeof spot.books !== 'object') spot.books = {}
  const kept = spot.books

  // ---- What handlers do: change the spot, and the next render shows it ----
  const touched = () => {
    touchedAt = Date.now()
  }
  const A = {
    ui,
    go: (change) => {
      touched()
      if (typeof change === 'function') change()
      else Object.assign(spot, change)
      if (!change || !('notice' in change)) delete spot.notice
      delete spot.sure
      spot.keys = false
      save()
    },
    turn: (by) => A.go({ cmd: by > 0 ? 'next' : 'prev' }),
    bookmark: () => A.go({ cmd: 'bookmark' }),
    page: (by) => A.go(() => {}),
    open: (i) => A.go({ cmd: 'open', openIndex: i }),
    draft: (text) => {
      drafts[spot.view] = text
    },
    prefs: (change) => A.go({ prefs: { ...prefs, ...change } }),
    pickFrom: (word) => A.go({ selm: { s: spot.at.s, p: spot.at.p || 0, a: [word[0], word[1]], z: [word[0], word[2]], phase: 'end', keys: false }, sheet: null }),
    pickTo: (word) =>
      A.go(() => {
        const selm = spot.selm
        if (!selm) return
        if (word[0] < selm.a[0] || (word[0] === selm.a[0] && word[1] < selm.a[1])) selm.a = [word[0], word[1]]
        else selm.z = [word[0], word[2]]
        selm.phase = 'end'
      }),
    keepPick: (note) => A.go({ cmd: note ? 'pickNote' : 'pick' }),
    placeAt: (f) => (A.book ? placeAt(A.book, f, ui) : { s: 0 }),
    goTo: (f) => A.go({ cmd: 'goto', gotoF: f }),
    goMark: (mark) => A.go({ cmd: 'goMark', markId: mark.id }),
    editNote: (mark) => {
      drafts.note = mark.n || ''
      A.go({ view: 'note', markId: mark.id })
    },
    saveNote: (mark) => A.go({ cmd: 'saveNote', markId: mark.id }),
    dropMark: (mark) => A.go({ cmd: 'dropMark', markId: mark.id }),
    exportAll: () => A.go({ cmd: 'export' }),
    importAll: () => A.go({ cmd: 'import' }),
    openPath: (path) => A.go({ cmd: 'openPath', openKey: keyOf('assets', path) }),
    download: (entry, path) =>
      A.go(() => {
        frameos.makeAssetFolder(home)
        spot.dl = startDownload(entry, path, Date.now())
      }),
    stopDownload: () =>
      A.go(() => {
        if (spot.dl && spot.dl.offset > 0) frameos.deleteAsset(spot.dl.path)
        spot.dl = null
      }),
  }

  // ---- A download going on: a few chunks a render, renders until done ----
  if (spot.dl && spot.dl.state === 'busy' && !writable) spot.dl = { ...spot.dl, state: 'failed', error: NO_CARD }
  if (spot.dl && spot.dl.state === 'busy') {
    if (now - touchedAt < 500) {
      // This render answers a press: the work goes on in the next one.
      touchedAt = 0
      frameos.setNextSleep(ui.fast ? 0.05 : 0.5)
    } else {
      let dl = spot.dl
      // Its folders, made before the first byte (a folder taken away since,
      // a job from before a restart).
      if (dl.offset === 0) {
        const parts = dl.path.split('/').slice(0, -1)
        for (let i = 1; i <= parts.length; i++) frameos.makeAssetFolder(parts.slice(0, i).join('/'))
      }
      // A download a restart cut short goes on from what is on the disk.
      if (dl.offset > 0) {
        const size = frameos.assetSize(dl.path)
        if (size !== dl.offset) dl = { ...dl, offset: size > 0 ? size : 0 }
      }
      const limits = { chunk: ui.embedded ? 64 * 1024 : 1024 * 1024, maxBytes: 200 * 1048576, lightAbove: ui.embedded ? 12 * 1048576 : 0 }
      const budget = ui.fast ? 400 : 25000
      const began = Date.now()
      while (dl.state === 'busy' && Date.now() - began < budget) {
        dl = stepDownload(dl, limits)
        if (dl.retries) break
      }
      spot.dl = dl
      if (dl.state === 'done') {
        forgetListing()
        spot.notice = `Downloaded ${dl.title}`
      }
      if (dl.state === 'busy') frameos.setNextSleep(ui.fast ? 0.05 : 0.5)
      save()
    }
  }

  // ---- A book another scene opened here (the Files app), where it was left ----
  const openKey = (key) => {
    const book = openAt(spot, key, ui)
    if (book.error) {
      spot.problem = `${bookName(key)}: ${book.error}`
      spot.view = 'library'
      return false
    }
    spot.book = key
    spot.view = 'book'
    spot.problem = ''
    spot.sheet = null
    spot.selm = null
    spot.last = { key, t: now }
    keepPlace(spot, book, now)
    return true
  }
  const handed = typeof app.state.file === 'string' ? normalKey(app.state.file.trim(), storages) : ''
  if (handed) {
    frameos.setState('file', '')
    openKey(handed)
  }

  // ---- Exports and imports, from wherever they were asked ----
  const exportNotes = () => {
    if (!writable) {
      spot.notice = NO_CARD
      return
    }
    frameos.makeAssetFolder(home)
    frameos.makeAssetFolder(notesFolder)
    let files = 0
    let ok = true
    for (const key of Object.keys(marks)) {
      const entry = marks[key]
      if (!entry || !Array.isArray(entry.list) || entry.list.length === 0) continue
      ok = frameos.writeAsset(`${notesFolder}/${fileName(entry.title)}.md`, toMarkdown(entry, now), { text: true }) && ok
      files++
    }
    ok = frameos.writeAsset(`${notesFolder}/${CLIPPINGS_NAME}`, toClippings(marks), { text: true }) && ok
    ok = frameos.writeAsset(`${notesFolder}/${BACKUP_NAME}`, toBackup(marks, spot, now), { text: true }) && ok
    spot.notice = ok
      ? `Saved to ${notesFolder}: ${files} book${files === 1 ? '' : 's'} as Markdown, ${CLIPPINGS_NAME}, the backup`
      : 'The frame could not write the notes: it needs room, and the scene permission to write files.'
  }
  const importNotes = () => {
    const text = frameos.readAsset(`${notesFolder}/${BACKUP_NAME}`, { text: true })
    if (!text) {
      spot.notice = `No backup to import: put "${BACKUP_NAME}" in ${notesFolder}.`
      return
    }
    const r = mergeBackup(text, marks, spot)
    if (r.error) {
      spot.notice = r.error
      return
    }
    saveMarks(marks)
    spot.notice = `Imported ${r.added} mark${r.added === 1 ? '' : 's'} and ${r.places} place${r.places === 1 ? '' : 's'}.`
  }

  // ---- A list the keys walk: which row is lit, which page shows ----
  const listFor = (name, rows, cmd, extra) => {
    const st = name === 'library' ? spot : ((spot.lists = spot.lists && typeof spot.lists === 'object' ? spot.lists : {})[name] = spot.lists[name] || {})
    let index = 0
    for (const row of rows) if (!row.header) row.index = index++
    const count = index
    if (typeof st.sel !== 'number' || st.sel < 0) st.sel = 0
    st.sel = Math.min(st.sel, Math.max(0, count - 1))
    let opened = null
    if (cmd === 'next') st.sel = Math.min(Math.max(0, count - 1), st.sel + 1)
    else if (cmd === 'prev') st.sel = Math.max(0, st.sel - 1)
    else if (cmd === 'select' && count > 0) opened = st.sel
    const pages = paginate(rows, listRoom(ui, extra))
    if (typeof st.page !== 'number' || cmd === 'next' || cmd === 'prev') st.page = pageOf(pages, st.sel)
    st.page = Math.max(0, Math.min(st.page, pages.length - 1))
    A.page = (by) => A.go(() => (st.page += by))
    return { pages, page: st.page, sel: st.sel, opened }
  }

  // ---- The views. Each returns what to draw, or null when it moved to another view ----

  const take = () => {
    const c = spot.cmd || null
    delete spot.cmd
    return c
  }
  let cmd = take()
  const result = (node, sheet) => ({ ui: node, sheet: !!sheet, look: ui })

  const bookViews = (cmd) => {
    const book = openBook(spot.book)
    if (book.error) {
      spot.view = 'library'
      spot.problem = `${bookName(spot.book)}: ${book.error}`
      return null
    }
    A.book = book
    if (!spot.at || typeof spot.at.s !== 'number' || spot.at.s >= book.spine.length) openAt(spot, spot.book, ui)
    const g = geometry(ui, prefs, book)
    const list = listOf(marks, book.path)
    const toc = book.toc || []
    const chapterName = (s) => {
      let label = `Chapter ${s + 1}`
      for (const entry of toc) if (entry.s <= s) label = entry.label
      return label
    }

    if (spot.view === 'book') {
      let spread = spreadOf(spot, book, g, ui)
      // Picking a passage with the keys.
      if (spot.selm && spot.selm.keys && cmd && ['next', 'prev', 'select', 'back'].includes(cmd)) {
        const selm = spot.selm
        const blocks = chapterOf(book, selm.s, selm.p, ui).blocks
        if (cmd === 'back') spot.selm = null
        else if (cmd === 'select') {
          if (selm.phase === 'start') selm.phase = 'end'
          else cmd = 'pick'
        } else {
          const by = cmd === 'next' ? 1 : -1
          if (selm.phase === 'start') {
            selm.a = stepStart(blocks, selm.a, by)
            selm.z = [selm.a[0], sentenceEnds(blocks[selm.a[0]].t).find((x) => x > selm.a[1]) || blocks[selm.a[0]].t.length]
          } else selm.z = stepEnd(blocks, selm.z, selm.a, by)
          // The page follows the end being moved.
          const point = selm.phase === 'start' ? selm.a : selm.z
          const startOf = spread.pg.starts[spread.pg.i]
          if (spread.end && (point[0] > spread.end[0] || (point[0] === spread.end[0] && point[1] > spread.end[1]))) turn(spot, book, 1, g, ui)
          else if (point[0] < startOf[0] || (point[0] === startOf[0] && point[1] < startOf[1])) turn(spot, book, -1, g, ui)
          spread = spreadOf(spot, book, g, ui)
        }
        if (cmd !== 'pick') cmd = null
      }
      if (cmd) {
        const path = book.path
        if (cmd === 'pick' || cmd === 'pickNote') {
          const selm = spot.selm
          if (selm) {
            const r = normal(selm)
            const chapter = chapterOf(book, selm.s, selm.p, ui)
            const mark = {
              id: newId(now),
              k: 'h',
              s: selm.s,
              p: selm.p,
              b: r.b,
              c: r.c,
              b2: r.b2,
              c2: r.c2,
              t: textBetween(chapter.blocks, r.b, r.c, r.b2, r.c2).slice(0, MAX_TEXT),
              n: '',
              at: now,
              f: shareOf(book, { s: selm.s, p: selm.p, b: r.b, c: r.c }, chapter, ui),
              ch: chapterName(selm.s),
            }
            putMark(marks, book, mark)
            saveMarks(marks)
            spot.selm = null
            if (cmd === 'pickNote') {
              drafts.note = ''
              spot.view = 'note'
              spot.markId = mark.id
              return null
            }
          }
        } else if (spot.selm && cmd === 'back') {
          spot.selm = null
        } else if (spot.sheet && (cmd === 'back' || cmd === 'select')) {
          spot.sheet = null
        } else if (cmd === 'next' || cmd === 'prev') {
          const from = { ...spot.at }
          const was = spread.chapter
          const moved = turn(spot, book, cmd === 'next' ? 1 : -1, g, ui)
          let chars = 0
          if (moved && cmd === 'next') {
            const fromChars = charsBefore(was.blocks, from.b, from.c)
            chars = spot.at.s === from.s && spot.at.p === from.p ? charsBefore(was.blocks, spot.at.b, spot.at.c) - fromChars : was.chars - fromChars
          }
          countTurn(spot, path, chars, now, cmd === 'next' && moved)
          if (!moved && cmd === 'next') {
            spot.sheet = 'end'
            kept[path] = kept[path] || {}
            kept[path].done = kept[path].done || now
          }
          spot.selm = spot.selm && spot.selm.s === spot.at.s && spot.selm.p === spot.at.p ? spot.selm : null
          spread = spreadOf(spot, book, g, ui)
        } else if (cmd === 'select') {
          spot.view = 'menu'
          spot.lists = null
          return null
        } else if (cmd === 'back') {
          countTurn(spot, path, 0, now, false)
          spot.last = null
          spot.view = 'library'
          return null
        } else if (cmd === 'bookmark') {
          const there = bookmarkOn(list, spot.at, spread.end)
          if (there) dropMark(marks, path, there.id)
          else {
            const words = []
            for (const page of spread.pages) for (const line of page.lines) if (line.t && words.join(' ').length < 160) words.push(line.t)
            putMark(marks, book, {
              id: newId(now),
              k: 'b',
              s: spot.at.s,
              p: spot.at.p || 0,
              b: spot.at.b || 0,
              c: spot.at.c || 0,
              t: cut(words.join(' '), 160),
              at: now,
              f: shareOf(book, spot.at, spread.chapter, ui),
              ch: chapterName(spot.at.s),
            })
          }
          saveMarks(marks)
        } else if (cmd === 'goto') {
          jumpTo(spot, placeAt(book, spot.gotoF || 0, ui))
          spot.sheet = null
          spread = spreadOf(spot, book, g, ui)
        } else if (cmd === 'pickKeys') {
          // "Highlight a passage" from the menu: its first sentence, moved with the keys.
          const start = spread.pg.starts[spread.pg.i]
          const blocks = spread.chapter.blocks
          let b = start[0]
          while (b < blocks.length - 1 && !blocks[b].t) b++
          const t = (blocks[b] && blocks[b].t) || ''
          const c = Math.min(start[0] === b ? start[1] : 0, Math.max(0, t.length - 1))
          spot.selm = { s: spot.at.s, p: spot.at.p || 0, a: [b, c], z: [b, sentenceEnds(t).find((x) => x > c) || t.length], phase: 'start', keys: true }
        }
      }
      const listNow = listOf(marks, book.path)
      const share = shareOf(book, spot.at, spread.chapter, ui)
      const left = charsLeft(book, spot.at, spread.chapter, ui)
      const speed = readingSpeed(spot)
      const leftSecs = { chapter: left.chapter / speed, book: left.book / speed }
      keepPlace(spot, book, now, share, leftSecs.book)
      if (!spot.last || spot.last.key !== book.path) spot.last = { key: book.path, t: now }
      save()
      return result(
        <Reader
          ui={ui}
          spot={spot}
          book={book}
          g={g}
          prefs={prefs}
          spread={spread}
          marks={listNow}
          bookmark={bookmarkOn(listNow, spot.at, spread.end)}
          share={share}
          left={leftSecs}
          A={A}
        />,
        true,
      )
    }

    if (spot.view === 'menu') {
      const spread = spreadOf(spot, book, g, ui)
      const marked = bookmarkOn(list, spot.at, spread.end)
      const highlights = list.filter((m) => m.k === 'h').length
      const share = shareOf(book, spot.at, spread.chapter, ui)
      const items = [
        { label: 'Back to the page', sub: `${Math.round(share * 100)}% · ${chapterName(spot.at.s)}`, icon: I.book, to: { view: 'book' } },
        { label: 'Contents', sub: `${toc.length || book.spine.length} ${toc.length ? 'entries' : 'chapters'}`, icon: I.list, to: { view: 'contents', tab: 'toc', lists: null } },
        { label: 'Bookmarks and highlights', sub: list.length ? `${list.length - highlights} bookmarks, ${highlights} highlights` : 'None yet', icon: I.quote, to: { view: 'contents', tab: 'marks', lists: null } },
        { label: marked ? 'Remove the bookmark' : 'Bookmark this page', icon: marked ? I.ribbon : I.ribbonLine, to: { view: 'book', cmd: 'bookmark' } },
        { label: 'Highlight a passage', sub: 'Pick where it starts and ends', icon: I.pen, to: { view: 'book', cmd: 'pickKeys' } },
        { label: 'Find in the book', icon: I.search, to: { view: 'find', lists: null } },
        { label: 'Go to a place', icon: I.flag, to: { view: 'book', sheet: 'goto', gotoF: share } },
        { label: 'Text and layout', sub: `${prefs.justify ? 'Justified' : 'Left aligned'} · ${['tight', 'normal', 'loose'][prefs.spacing]} spacing`, icon: I.type, to: { view: 'book', sheet: 'type' } },
        { label: 'Export notes', sub: spot.notice || `Markdown, My Clippings.txt and a backup, into ${notesFolder}`, icon: I.share, to: { cmd: 'export' } },
        { label: 'Library', icon: I.folder, to: { view: 'library' } },
      ]
      const rows = items.map((item) => ({ ...item, height: item.sub ? 56 : 48 }))
      const pick = (i) => {
        const item = items[i]
        if (!item) return
        Object.assign(spot, item.to)
        spot.keys = false
      }
      if (cmd === 'back') {
        spot.view = 'book'
        return null
      }
      const l = listFor('menu', rows, cmd)
      if (l.opened !== null) {
        pick(l.opened)
        if (spot.cmd === 'export') {
          delete spot.cmd
          exportNotes()
        }
        return null
      }
      A.open = (i) =>
        A.go(() => {
          pick(i)
          if (spot.cmd === 'export') {
            delete spot.cmd
            exportNotes()
            spot.view = 'menu'
          }
        })
      save()
      return result(<ListPage ui={ui} spot={spot} title={book.title} sub={book.author} list={l} A={A} onBack={() => A.go({ view: 'book' })} onOpen={(i) => A.open(i)} />)
    }

    if (spot.view === 'contents') {
      const tab = spot.tab === 'marks' ? 'marks' : 'toc'
      if (cmd === 'back') {
        spot.view = 'book'
        return null
      }
      let current = 0
      toc.forEach((entry, i) => {
        if (entry.s <= spot.at.s) current = i
      })
      const rows =
        tab === 'toc'
          ? (toc.length ? toc : book.spine.map((x, s) => ({ label: `Chapter ${s + 1}`, s }))).map((entry, i) => ({ label: entry.label, bold: toc.length ? i === current : entry.s === spot.at.s, height: 46, go: entry }))
          : list.map((m) => ({
              label: m.k === 'b' ? `Bookmark · ${m.ch || `Chapter ${m.s + 1}`}` : `“${cut(m.t, 140)}”`,
              sub: [m.k === 'h' ? m.ch || `Chapter ${m.s + 1}` : cut(m.t, 80), `${Math.round((m.f || 0) * 100)}%`, m.n ? `✎ ${cut(m.n, 60)}` : ago(m.at, now)].filter(Boolean).join(' · '),
              icon: m.k === 'b' ? I.ribbonLine : m.n ? I.pen : I.quote,
              height: 58,
              mark: m,
            }))
      const name = `contents-${tab}`
      spot.lists = spot.lists && typeof spot.lists === 'object' ? spot.lists : {}
      if (tab === 'toc' && !spot.lists[name]) spot.lists[name] = { sel: current }
      const l = listFor(name, rows, cmd, 40)
      const openRow = (i) => {
        const row = rows.find((r) => r.index === i)
        if (!row) return
        if (row.go) {
          jumpTo(spot, { s: row.go.s, p: 0, b: 0, c: 0 })
          spot.view = 'book'
          keepPlace(spot, book, now)
        } else if (row.mark) {
          spot.view = 'mark'
          spot.markId = row.mark.id
        }
      }
      if (l.opened !== null) {
        openRow(l.opened)
        return null
      }
      save()
      const tabBtn = (id, label) => <Btn ui={ui} small size={32} label={label} on={tab === id} onClick={() => A.go({ tab: id })} />
      return result(
        <ListPage
          ui={ui}
          spot={spot}
          title={tab === 'toc' ? 'Contents' : 'Marks'}
          sub={book.title}
          list={l}
          A={A}
          onBack={() => A.go({ view: 'book' })}
          onOpen={(i) => A.go(() => openRow(i))}
          tabs={[tabBtn('toc', 'Contents'), tabBtn('marks', `Marks${list.length ? ` (${list.length})` : ''}`), <div className="flex-1" />, tab === 'marks' && list.length ? <Btn ui={ui} small size={32} icon={I.share} label="Export" onClick={() => A.exportAll()} /> : null]}
          footer={spot.notice ? <span className={`truncate text-[${px(12)}] ${ui.muted}`}>{spot.notice}</span> : null}
          empty={tab === 'toc' ? 'This book has no contents.' : 'No marks yet. The ribbon at the top bookmarks a page; a long press on a word starts a highlight.'}
        />,
      )
    }

    if (spot.view === 'mark' || spot.view === 'note') {
      const mark = findMark(marks, book.path, spot.markId)
      if (!mark) {
        spot.view = 'contents'
        spot.tab = 'marks'
        return null
      }
      if (cmd === 'back') {
        spot.view = spot.view === 'note' ? 'mark' : 'contents'
        return null
      }
      if (cmd === 'goMark') {
        jumpTo(spot, mark)
        spot.view = 'book'
        return null
      }
      if (cmd === 'dropMark') {
        dropMark(marks, book.path, mark.id)
        saveMarks(marks)
        spot.view = 'contents'
        spot.tab = 'marks'
        return null
      }
      if (cmd === 'saveNote') {
        putMark(marks, book, { ...mark, n: String(drafts.note || '').trim().slice(0, 2000) })
        saveMarks(marks)
        spot.view = 'mark'
        return null
      }
      save()
      if (spot.view === 'note') return result(<NoteView ui={ui} mark={mark} text={drafts.note === undefined ? mark.n || '' : drafts.note} A={A} />)
      return result(<MarkView ui={ui} spot={spot} mark={mark} A={A} book={book} now={now} />)
    }

    if (spot.view === 'find') {
      const find = spot.find && typeof spot.find === 'object' && spot.find.path === book.path ? spot.find : { path: book.path, q: '', hits: [], done: true }
      if (cmd === 'back') {
        spot.view = 'book'
        return null
      }
      if (cmd === 'find') {
        const q = String(drafts.find || '').trim()
        Object.assign(find, { q, hits: [], s: spot.at.s, p: 0, from: spot.at.s, wrapped: false, done: q.length < 2, more: false })
        spot.lists = null
      }
      // Searching, a few chapters a render, from the chapter you are in.
      if (find.q && !find.done) {
        const began = Date.now()
        const budget = ui.fast ? 500 : 20000
        const needle = find.q.toLowerCase()
        while (!find.done && Date.now() - began < budget) {
          const chapter = chapterOf(book, find.s, find.p, ui)
          chapter.blocks.forEach((block, b) => {
            if (!block.t || find.hits.length >= 80) return
            const t = block.t.toLowerCase()
            let at = t.indexOf(needle)
            while (at >= 0 && find.hits.length < 80) {
              const from = Math.max(0, at - 30)
              find.hits.push({ s: find.s, p: find.p, b, c: at, t: `${from > 0 ? '…' : ''}${block.t.slice(from, at + needle.length + 70)}` })
              at = t.indexOf(needle, at + needle.length)
            }
          })
          if (chapter.more) find.p++
          else {
            find.p = 0
            find.s = (find.s + 1) % book.spine.length
            if (find.s === 0) find.wrapped = true
          }
          if (find.s === find.from && find.p === 0) find.done = true
          if (find.hits.length >= 80) {
            find.done = true
            find.more = true
          }
        }
        if (!find.done) frameos.setNextSleep(ui.fast ? 0.05 : 0.5)
      }
      spot.find = find
      const rows = find.hits.map((hit) => ({ label: cut(hit.t, 120), sub: `${chapterName(hit.s)}`, icon: I.search, height: 56, hit }))
      const l = listFor('find', rows, cmd === 'find' ? null : cmd, 54)
      const openHit = (i) => {
        const row = rows.find((r) => r.index === i)
        if (!row) return
        jumpTo(spot, row.hit)
        spot.view = 'book'
      }
      if (l.opened !== null) {
        openHit(l.opened)
        return null
      }
      save()
      const value = drafts.find === undefined ? find.q : drafts.find
      return result(
        <ListPage
          ui={ui}
          spot={spot}
          title="Find in the book"
          sub={find.q ? (find.done ? `${find.hits.length}${find.more ? '+' : ''} found for “${find.q}”` : `Looking for “${find.q}”…`) : book.title}
          list={l}
          A={A}
          onBack={() => A.go({ view: 'book' })}
          onOpen={(i) => A.go(() => openHit(i))}
          tabs={[
            <input
              className={`flex-1 min-w-0 h-[${px(36)}] px-[${px(10)}] rounded-[${px(8)}] text-[${px(16)}] ${ui.card} focus:border-2 focus:border-[${ui.accentColor}]`}
              value={value}
              placeholder="A word or a phrase"
              onChange={(e) => A.draft(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') A.go({ cmd: 'find' })
              }}
            />,
            <Btn ui={ui} small size={36} primary icon={I.search} label="Find" onClick={() => A.go({ cmd: 'find' })} />,
          ]}
          empty={find.q ? (find.done ? 'Not in this book.' : 'Looking…') : 'Type what to look for, then Find.'}
        />,
      )
    }
    spot.view = 'book'
    return null
  }

  // ---- The library ----
  const libraryView = (cmd) => {
    if (cmd === 'openPath' && spot.openKey) {
      const key = spot.openKey
      delete spot.openKey
      if (openKey(key)) return null
    }
    // Time read since the last page turn, when the book was left.
    if (spot.last && spot.last.key) {
      countTurn(spot, spot.last.key, 0, now, false)
      spot.last = null
    }
    if (cmd === 'back' && spot.book && kept[spot.book]) {
      spot.view = 'book'
      return null
    }
    const fresh = spot.refresh === true
    delete spot.refresh
    if (fresh) {
      spot.shelf = {}
      metas.clear()
    }
    const order = storages.map((s) => s.id)
    let all = booksIn(folder, storages, fresh)
    // A key on an empty library (before it was known to be empty) looks again.
    if (cmd === 'select' && all.length === 0 && !fresh) {
      forgetListing()
      all = booksIn(folder, storages, true)
    }
    spot.empty = all.length === 0
    if (!spot.empty) delete spot.looked
    else if (fresh) spot.looked = true
    const sort = spot.sort || 'recent'
    const meta = (key) => {
      const place = kept[key]
      return place && place.title && 'cover' in place ? { title: place.title, author: place.author, cover: place.cover } : (spot.shelf && spot.shelf[key]) || metas.get(key) || null
    }
    const title = (key) => ((meta(key) && meta(key).title) || bookName(key)).toLowerCase()
    const author = (key) => ((meta(key) && meta(key).author) || '').toLowerCase()
    const books = all.slice().sort((a, b) => {
      const sa = order.indexOf(placeOf(a).storage)
      const sb = order.indexOf(placeOf(b).storage)
      if (sort === 'title') return sa - sb || title(a).localeCompare(title(b))
      if (sort === 'author') return sa - sb || author(a).localeCompare(author(b)) || title(a).localeCompare(title(b))
      const ta = (kept[a] && kept[a].t) || 0
      const tb = (kept[b] && kept[b].t) || 0
      return sa - sb || tb - ta || bookName(a).toLowerCase().localeCompare(bookName(b).toLowerCase())
    })
    const filter = spot.filter || 'all'
    const shown = books.filter((key) => (filter === 'done' ? kept[key] && kept[key].done : filter === 'reading' ? kept[key] && !kept[key].done && kept[key].f > 0 : true))
    // What the shelf keeps of books no longer listed goes.
    if (spot.shelf && typeof spot.shelf === 'object') for (const key of Object.keys(spot.shelf)) if (!all.includes(key)) delete spot.shelf[key]

    const rows = []
    const current = spot.book && kept[spot.book] && !kept[spot.book].done && all.includes(spot.book) && filter !== 'done' ? spot.book : null
    if (current) rows.push({ key: current, cont: true, height: 78 })
    shown.forEach((key, i) => {
      const storage = placeOf(key).storage
      if (storages.length > 1 && (i === 0 || placeOf(shown[i - 1]).storage !== storage)) {
        const named = storages.find((s) => s.id === storage)
        rows.push({ header: true, label: named ? named.name : storage, height: 34 })
      }
      rows.push({ key, height: 62 })
    })
    if (all.length > 0 && shown.length === 0) rows.push({ header: true, label: filter === 'done' ? 'No finished books yet.' : 'Nothing being read: open a book from All.', height: 44 })
    if (all.length > 0) {
      rows.push({ action: { view: 'catalog', lists: null }, label: 'Get free books', sub: 'Project Gutenberg, Standard Ebooks and your catalogs', icon: I.download, height: 56 })
      rows.push({ action: { view: 'stats' }, label: 'Reading stats and notes', sub: 'Your time, pace and streak; export and import', icon: I.chart, height: 56 })
    }
    const l = listFor('library', rows, cmd === 'open' ? null : cmd, all.length ? 40 : 0)
    const openRow = (i) => {
      const row = rows.find((r) => r.index === i)
      if (!row) return false
      if (row.action) {
        Object.assign(spot, row.action)
        return true
      }
      return openKey(row.key)
    }
    if (l.opened !== null && openRow(l.opened)) return null
    if (cmd === 'open' && typeof spot.openIndex === 'number') {
      const i = spot.openIndex
      delete spot.openIndex
      if (openRow(i)) {
        spot.sel = i
        return null
      }
    }
    // Titles and covers for the page showing (the shelf keeps them), the
    // covers small, decoded once while the app lives.
    const showing = new Set((l.pages[l.page] || []).filter((row) => row.key).map((row) => row.key))
    for (const row of rows) {
      if (!row.key) continue
      const m = meta(row.key)
      row.meta = m && m.title ? m : showing.has(row.key) ? metaOf(row.key, spot) : { title: bookName(row.key), author: '' }
    }
    save()
    const thumb = (row) => (row.cont ? [Math.round(46 * Z.zoom), Math.round(64 * Z.zoom)] : [Math.round(36 * Z.zoom), Math.round(50 * Z.zoom)])
    const coverKey = (row) => `${row.key}|${row.meta.cover}|${thumb(row).join('x')}`
    const covers = picturesFor(
      rows.filter((row) => row.key && row.meta.cover && showing.has(row.key)).map((row) => ({ key: coverKey(row), path: row.key, src: row.meta.cover, w: thumb(row)[0], h: thumb(row)[1], fit: 'cover' })),
      ui.paperColor,
    )
    for (const row of rows) {
      if (!row.key) continue
      const place = kept[row.key]
      const share = place && place.f ? place.f : 0
      const left = place && place.left > 0 ? `${duration(place.left)} left` : ''
      const progress = place && place.done ? 'Finished' : share > 0 ? [`${Math.floor(share * 100)}%`, left].filter(Boolean).join(' · ') : row.meta.error ? row.meta.error : 'Not started'
      row.label = row.cont ? row.meta.title : row.meta.title
      row.sub = row.cont ? [`Continue reading`, progress].join(' · ') : [row.meta.author, progress].filter(Boolean).join(' · ')
      row.bold = row.cont || row.key === spot.book
      row.share = place && !place.done ? share : undefined
      row.thumb = (row.meta.cover && covers.get(coverKey(row))) || null
      row.thumbW = thumb(row)[0]
      row.thumbH = thumb(row)[1]
      row.right = row.cont ? '' : place && place.done ? '✓' : ''
    }
    const names = storages.map((s) => (s.id === 'assets' && s.name === 'TF card' ? 'the TF card' : s.name.toLowerCase().replace(/^internal/, 'the internal')))
    const where = `${folder ? `the folder "${folder}" on ` : ''}${names.join(' or ')}`
    return result(<LibraryView ui={ui} list={l} A={A} spot={spot} count={all.length} where={where} notice={spot.problem || spot.notice || (spot.dl && spot.dl.state === 'busy' ? `Downloading ${spot.dl.title}…` : '')} />)
  }

  // ---- Reading stats ----
  const statsView = (cmd) => {
    if (cmd === 'back') {
      spot.view = 'library'
      return null
    }
    if (spot.last && spot.last.key) {
      countTurn(spot, spot.last.key, 0, now, false)
      spot.last = null
    }
    const s = summary(spot, now)
    const top = Object.keys(kept)
      .map((key) => kept[key])
      .filter((b) => b.secs > 0)
      .sort((a, b) => (b.t || 0) - (a.t || 0))
      .slice(0, ui.height / Z.zoom > 600 ? 8 : 4)
    save()
    return result(<StatsView ui={ui} s={s} top={top} A={A} notice={spot.notice} />)
  }

  // ---- The catalogs ----
  const catOf = () => (spot.cat && typeof spot.cat === 'object' ? spot.cat : (spot.cat = {}))
  const pathFor = (entry) => `${home}/${bookFile(entry)}`
  const downloading = spot.dl && spot.dl.state === 'busy' ? spot.dl : null
  const dlFooter = downloading ? <span className={`truncate text-[${px(12)}] ${ui.muted}`}>{`Downloading ${downloading.title}: ${sizeText(downloading.offset)}${downloading.total ? ` of ${sizeText(downloading.total)}` : ''}`}</span> : spot.notice ? <span className={`truncate text-[${px(12)}] ${ui.muted}`}>{spot.notice}</span> : null

  const catalogView = (cmd) => {
    if (cmd === 'back') {
      spot.view = 'library'
      return null
    }
    const rows = [
      { label: 'Project Gutenberg', sub: 'Over 75,000 free books: popular, by shelf, or search', icon: I.globe, height: 58, to: { view: 'shelves', lists: null } },
      { label: 'Standard Ebooks', sub: 'The newest of its carefully made classics', icon: I.globe, height: 58, to: { view: 'feed', cat: { kind: 'atom', url: SE_FEED, title: 'Standard Ebooks', stack: [] }, lists: null } },
      ...feeds.map((feed) => ({ label: feed.name, sub: hostOf(feed.url), icon: I.folder, height: 58, to: { view: 'feed', cat: { kind: 'atom', url: feed.url, title: feed.name, stack: [] }, lists: null } })),
      { label: 'Search Project Gutenberg', icon: I.search, height: 50, to: { view: 'search', searchIn: 'pg' } },
      { label: 'A book from its address', sub: 'Any .epub on the web', icon: I.link, height: 56, to: { view: 'link' } },
    ]
    const l = listFor('catalog', rows, cmd)
    if (l.opened !== null) {
      Object.assign(spot, rows.find((r) => r.index === l.opened).to)
      return null
    }
    save()
    return result(
      <ListPage
        ui={ui}
        spot={spot}
        title="Get books"
        sub={writable ? `Downloaded into ${home}` : NO_CARD}
        list={l}
        A={A}
        onBack={() => A.go({ view: 'library' })}
        onOpen={(i) => A.go(rows.find((r) => r.index === i).to)}
        footer={dlFooter}
        empty=""
      />,
    )
  }

  const shelvesView = (cmd) => {
    if (cmd === 'back') {
      spot.view = 'catalog'
      return null
    }
    const rows = [
      { label: 'Search', icon: I.search, height: 48, to: { view: 'search', searchIn: 'pg' } },
      ...SHELVES.map((shelf) => ({ label: shelf.label, icon: shelf.topic ? I.folder : I.chart, height: 48, to: { view: 'feed', cat: { kind: 'pg', topic: shelf.topic, title: shelf.label, page: 1, stack: [] }, lists: null } })),
    ]
    const l = listFor('shelves', rows, cmd)
    if (l.opened !== null) {
      Object.assign(spot, rows.find((r) => r.index === l.opened).to)
      return null
    }
    save()
    return result(
      <ListPage
        ui={ui}
        spot={spot}
        title="Project Gutenberg"
        sub={languages ? `Books in ${languages.split(',').join(', ').toUpperCase()}` : 'Books in every language'}
        list={l}
        A={A}
        onBack={() => A.go({ view: 'catalog', lists: null })}
        onOpen={(i) => A.go(rows.find((r) => r.index === i).to)}
        footer={dlFooter}
        empty=""
      />,
    )
  }

  const feedView = (cmd) => {
    const cat = catOf()
    const parent = cat.kind === 'pg' ? (cat.search ? 'search' : 'shelves') : 'catalog'
    const back = () => {
      if (cat.stack && cat.stack.length) {
        const prev = cat.stack.pop()
        Object.assign(cat, prev)
        spot.lists = null
      } else spot.view = parent === 'search' ? 'shelves' : parent
    }
    if (cmd === 'back') {
      back()
      return null
    }
    let feed = { entries: [], next: false }
    let state = { loading: true }
    if (cat.kind === 'pg') {
      state = load(gutendexUrl({ topic: cat.topic, search: cat.search, languages, page: cat.page || 1 }), false)
      if (state.data) feed = fromGutendex(state.data)
    } else if (cat.url) {
      state = load(cat.url, true)
      if (state.data) {
        feed = parseAtom(state.data, cat.url)
        cat.searchTpl = feed.search || ''
        cat.searchDoc = feed.searchDoc || ''
        if (!cat.title) cat.title = feed.title
      }
    }
    const rows = feed.entries.map((entry) => ({
      label: entry.title,
      sub: entry.nav ? 'A catalog' : [entry.author, entry.downloads ? `${thousands(entry.downloads)} downloads` : ''].filter(Boolean).join(' · '),
      thumb: entry.cover || null,
      icon: entry.nav ? I.folder : I.book,
      thumbW: Math.round(36 * Z.zoom),
      thumbH: Math.round(50 * Z.zoom),
      height: 62,
      entry,
    }))
    if (feed.next) rows.push({ label: 'More books', icon: I.right, height: 50, more: true })
    const l = listFor('feed', rows, cmd)
    const openRow = (i) => {
      const row = rows.find((r) => r.index === i)
      if (!row) return
      if (row.more) {
        cat.stack = cat.stack || []
        if (cat.kind === 'pg') {
          cat.stack.push({ page: cat.page || 1 })
          cat.page = (cat.page || 1) + 1
        } else {
          cat.stack.push({ url: cat.url })
          cat.url = feed.next
        }
        spot.lists = null
      } else if (row.entry.nav) {
        cat.stack = cat.stack || []
        cat.stack.push({ url: cat.url, title: cat.title })
        cat.url = row.entry.nav
        cat.title = row.entry.title
        spot.lists = null
      } else {
        const e = row.entry
        cat.entry = { ...e, summary: cut(e.summary, 1200) }
        spot.view = 'entry'
      }
    }
    if (l.opened !== null) {
      openRow(l.opened)
      return null
    }
    save()
    const canSearch = cat.kind === 'pg' || cat.searchTpl || cat.searchDoc
    return result(
      <ListPage
        ui={ui}
        spot={spot}
        title={cat.title || 'Catalog'}
        sub={state.loading && !state.data ? 'Loading…' : state.error ? state.error : cat.kind === 'pg' ? `Project Gutenberg${(cat.page || 1) > 1 ? ` · page ${cat.page}` : ''}` : hostOf(cat.url)}
        list={l}
        A={A}
        onBack={() => A.go(back)}
        onOpen={(i) => A.go(() => openRow(i))}
        actions={canSearch ? <Btn ui={ui} icon={I.search} onClick={() => A.go({ view: 'search', searchIn: cat.kind === 'pg' ? 'pg' : 'feed' })} /> : null}
        footer={dlFooter}
        empty={state.loading && !state.data ? 'Loading…' : state.error || 'Nothing here.'}
      />,
    )
  }

  const entryView = (cmd) => {
    const cat = catOf()
    const entry = cat.entry
    if (!entry || cmd === 'back') {
      spot.view = 'feed'
      return null
    }
    if (cmd === 'openPath' && spot.openKey) {
      const key = spot.openKey
      delete spot.openKey
      forgetListing()
      if (openKey(key)) return null
    }
    const path = spot.dl && spot.dl.title === entry.title && spot.dl.state !== 'failed' ? spot.dl.path : pathFor(entry)
    const exists = !(spot.dl && spot.dl.path === path && spot.dl.state === 'busy') && frameos.assetExists(path)
    save()
    return result(<EntryView ui={ui} entry={entry} A={A} dl={spot.dl} exists={exists} path={path} writable={writable} noCard={NO_CARD} onBack={() => A.go({ view: 'feed' })} />)
  }

  const searchView = (cmd) => {
    const cat = catOf()
    const inPg = spot.searchIn !== 'feed'
    if (cmd === 'back') {
      spot.view = inPg ? 'shelves' : 'feed'
      return null
    }
    let template = ''
    if (!inPg) {
      template = cat.searchTpl || ''
      if (!template && cat.searchDoc) {
        const doc = load(cat.searchDoc, true)
        if (doc.data) template = cat.searchTpl = searchTemplate(doc.data, cat.searchDoc)
      }
    }
    if (cmd === 'search') {
      const q = String(drafts.search || '').trim()
      if (q) {
        if (inPg) spot.cat = { kind: 'pg', search: q, title: `“${q}”`, page: 1, stack: [] }
        else if (template) {
          const stack = (cat.stack || []).concat([{ url: cat.url, title: cat.title }])
          spot.cat = { ...cat, url: template.replace('{searchTerms}', encodeURIComponent(q)).replace(/\{[^}]*\?\}/g, ''), title: `“${q}”`, stack }
        }
        spot.view = 'feed'
        spot.lists = null
        return null
      }
    }
    save()
    return result(
      <AskView
        ui={ui}
        title={inPg ? 'Search Project Gutenberg' : `Search ${cat.title || 'the catalog'}`}
        sub="A title, an author or a subject"
        value={drafts.search || ''}
        placeholder="Jane Austen, whales, Paris…"
        label="Search"
        A={A}
        onBack={() => A.go({ view: inPg ? 'shelves' : 'feed' })}
        onGo={() => A.go({ cmd: 'search' })}
        hint={!inPg && !template ? 'This catalog says nothing of a search.' : ''}
      />,
    )
  }

  const linkView = (cmd) => {
    if (cmd === 'back') {
      spot.view = 'catalog'
      return null
    }
    if (cmd === 'link') {
      const url = String(drafts.link || '').trim()
      if (/^https?:\/\/\S+$/i.test(url)) {
        const name = decodeURIComponent((url.split(/[?#]/)[0].split('/').pop() || 'book').replace(/\+/g, ' ')).replace(/\.epub$/i, '')
        const entry = { title: name || 'Book', author: '', summary: '', urls: [url], source: hostOf(url) }
        catOf().entry = entry
        frameos.makeAssetFolder(home)
        spot.dl = startDownload(entry, pathFor(entry), now)
        spot.view = 'entry'
        return null
      }
      spot.notice = 'That is no web address: it starts with https://'
    }
    save()
    return result(
      <AskView
        ui={ui}
        title="A book from its address"
        sub={`Downloaded into ${home}`}
        value={drafts.link || ''}
        placeholder="https://example.com/book.epub"
        label="Download"
        type="url"
        A={A}
        onBack={() => A.go({ view: 'catalog' })}
        onGo={() => A.go({ cmd: 'link' })}
        hint={spot.notice || 'An EPUB file on the web: a library, a publisher, your own server.'}
      />,
    )
  }

  // Exports and imports are asked from more than one page.
  if (cmd === 'export' || cmd === 'import') {
    if (cmd === 'export') exportNotes()
    else importNotes()
    cmd = null
  }
  const ROUTES = {
    stats: statsView,
    catalog: catalogView,
    shelves: shelvesView,
    feed: feedView,
    entry: entryView,
    search: searchView,
    link: linkView,
    library: libraryView,
  }
  for (let pass = 0; pass < 6; pass++) {
    if (!VIEWS.includes(spot.view) || (BOOK_VIEWS.includes(spot.view) && !spot.book)) spot.view = 'library'
    const out = BOOK_VIEWS.includes(spot.view) ? bookViews(cmd) : ROUTES[spot.view](cmd)
    if (out) return out
    // A view that moved on hands its command (if any) to the next.
    cmd = take()
  }
  save()
  return result(<div className={`w-full h-full ${ui.bg}`} />)
}

