// What every view shares: the look (a frame's panel, the reader's theme), the
// size of things, icons, a paged list the keys walk, and small controls.

// The UI's sizes are made for 480 px of the room's shorter side; `zoom` is
// how much larger or smaller this room has them (set by uiOf every render).
export const Z = { zoom: 1 }
export const px = (n) => `${Math.round(n * Z.zoom)}px`
export const raw = (n) => `${Math.round(n)}px`

// The reader's page colours. E-paper and a panel without colour read black on
// white whatever the theme says.
export const THEMES = {
  light: { page: '#fbf8f1', ink: '#1d1b18', muted: '#7a7368', soft: '#efe9dd', rule: '#c9c2b4', mark: '#f3dd8b', sel: '#b9d3f5' },
  sepia: { page: '#f1e7d0', ink: '#3b2f22', muted: '#7d6b52', soft: '#e4d6b8', rule: '#bfae8c', mark: '#e9c96f', sel: '#c4cfdc' },
  dark: { page: '#15171b', ink: '#d6d1c7', muted: '#8a8579', soft: '#262a31', rule: '#4a4d55', mark: '#6b5a1d', sel: '#24456e' },
}
export const THEME_NAMES = ['light', 'sepia', 'dark']

// The round panel's canvas when the scene draws one: the views go in the
// square inside the circle.
export const ROUND = { canvas: null }

export function uiOf(app, context, prefs) {
  const paper = app.frame.paper === true
  const ink = paper || app.frame.color === false
  const fast = app.frame.fast ?? !paper
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  // Sized for 480 px of the room's shorter side, smaller under it; a bigger
  // screen is made larger by the frame's render scale, not here, and one
  // twice that size or more at render scale 1 (a 13.3" e-paper) twice as
  // large here, so its whole panel is used, not its corner.
  const shortSide = Math.min(width, height)
  Z.zoom = shortSide >= 900 ? 2 : Math.max(0.75, Math.min(1, Math.round((shortSide / 480) * 4) / 4))
  const side = context && context.round === true ? Math.floor((Math.min(width, height) / 2 - 12) * Math.SQRT2) : 0
  if (side) ROUND.canvas = { width, height, side }
  const themeName = prefs && THEMES[prefs.theme] ? prefs.theme : 'light'
  const t = THEMES[themeName]
  const dark = !ink && themeName === 'dark'
  return {
    paper,
    ink,
    fast,
    slow: !fast,
    color: !ink,
    width: side || width,
    height: side || height,
    embedded: app.frame.embedded === true,
    themeName,
    // The book's page: its own theme on a screen, black on white on paper.
    sheet: ink ? 'bg-white text-black' : `bg-[${t.page}] text-[${t.ink}]`,
    paperColor: ink ? '#ffffff' : t.page,
    inkColor: ink ? '#000000' : t.ink,
    rule: ink ? '#000000' : t.rule,
    markColor: ink ? '#000000' : t.mark,
    selColor: ink ? '#000000' : t.sel,
    sheetMuted: ink ? 'text-black' : `text-[${t.muted}]`,
    sheetSoft: ink ? 'bg-white border-2 border-black text-black' : `bg-[${t.soft}] text-[${t.ink}]`,
    sheetLine: ink ? 'border-b-2 border-black' : `border-b border-[${t.rule}]`,
    // The library and the other pages: a dark screen, or paper.
    bg: ink ? 'bg-white' : 'bg-[#0b0e14]',
    text: ink ? 'text-black' : 'text-white',
    muted: ink ? 'text-black' : 'text-[#8b93a7]',
    soft: ink ? 'bg-white border-2 border-black text-black' : 'bg-[#232a3a] text-white',
    card: ink ? 'bg-white border-2 border-black' : 'bg-[#151b27]',
    accent: ink ? 'bg-black text-white' : 'bg-[#3b82f6] text-white',
    accentColor: ink ? '#000000' : '#3b82f6',
    track: ink ? '#ffffff' : '#232a3a',
    trackBorder: ink ? 'border border-black' : '',
    press: !fast ? '' : ink ? 'active:bg-black active:text-white' : 'active:bg-[#2c3550]',
    sheetPress: !fast ? '' : ink ? 'active:bg-black active:text-white' : dark ? 'active:bg-[#30353e]' : 'active:bg-[#e0d8c8]',
    line: ink ? 'border-b-2 border-black' : 'border-b border-[#1f2635]',
  }
}

// ---- Icons -------------------------------------------------------------------

export const Icon = ({ d, size, stroke, width }) => (
  <svg viewBox="0 0 24 24" className={`w-[${px(size)}] h-[${px(size)}] shrink-0`}>
    {stroke ? (
      <path fill="none" stroke="currentColor" strokeWidth={width || 2.2} strokeLinecap="round" strokeLinejoin="round" d={d} />
    ) : (
      <path fill="currentColor" d={d} />
    )}
  </svg>
)

export const I = {
  book: 'M4 4.5A1.5 1.5 0 0 1 5.5 3H19v15H5.5A1.5 1.5 0 0 0 4 19.5Z M4 19.5A1.5 1.5 0 0 0 5.5 21H19v-3',
  left: 'M15 5L8 12L15 19',
  right: 'M9 5L16 12L9 19',
  list: 'M4 5h3v3H4ZM9 5.5h11v2H9ZM4 10.5h3v3H4ZM9 11h11v2H9ZM4 16h3v3H4ZM9 16.5h11v2H9Z',
  refresh: 'M19 12a7 7 0 1 1-2.05-4.95M19 4v4h-4',
  ribbon: 'M6 3h12v18l-6-4.5L6 21Z',
  ribbonLine: 'M6.5 3.5h11v16.5l-5.5-4.2l-5.5 4.2Z',
  type: 'M3 19L8.5 5h1L15 19M5.2 14h7.6M15.5 19l3-8h1l3 8M16.4 16.5h5.2',
  menu: 'M4 6h16M4 12h16M4 18h16',
  download: 'M12 4v11M7 10.5l5 5l5-5M5 20h14',
  chart: 'M5 20V11M10 20V5M15 20v-7M20 20V9',
  search: 'M10.5 4a6.5 6.5 0 1 1 0 13a6.5 6.5 0 0 1 0-13ZM15.5 15.5L20 20',
  pen: 'M4 20l1-4L16.5 4.5l3 3L8 19ZM14 7l3 3',
  quote: 'M5 17c2-1 3-3 3-6H5V6h5v5c0 4-2 6.5-5 7.5ZM14 17c2-1 3-3 3-6h-3V6h5v5c0 4-2 6.5-5 7.5Z',
  trash: 'M5 7h14M10 7V4.5h4V7M7 7l1 13h8l1-13',
  close: 'M6 6l12 12M18 6L6 18',
  check: 'M5 12.5l4.5 4.5L19 7',
  globe: 'M12 3a9 9 0 1 1 0 18a9 9 0 0 1 0-18ZM3 12h18M12 3c2.5 2.5 3.5 5.5 3.5 9s-1 6.5-3.5 9c-2.5-2.5-3.5-5.5-3.5-9s1-6.5 3.5-9Z',
  link: 'M10 14a4 4 0 0 0 5.7 0l3-3a4 4 0 0 0-5.7-5.7l-1 1M14 10a4 4 0 0 0-5.7 0l-3 3a4 4 0 0 0 5.7 5.7l1-1',
  share: 'M12 15V3M7.5 7.5L12 3l4.5 4.5M5 13v7h14v-7',
  inbox: 'M12 3v10M7.5 8.5L12 13l4.5-4.5M5 13v7h14v-7',
  folder: 'M3 6.5A1.5 1.5 0 0 1 4.5 5H9l2 2.5h8.5A1.5 1.5 0 0 1 21 9v9.5a1.5 1.5 0 0 1-1.5 1.5h-15A1.5 1.5 0 0 1 3 18.5Z',
  clock: 'M12 3a9 9 0 1 1 0 18a9 9 0 0 1 0-18ZM12 7v5l3.5 2',
  flag: 'M5 21V4M5 4h11l-2 4l2 4H5',
}

// ---- Controls ------------------------------------------------------------------

// A button: an icon, a label or both. `on` is a pressed toggle.
export function Btn({ ui, label, icon, onClick, primary, on, size, sheet, grow, small }) {
  const h = size || 40
  const look = primary || on ? ui.accent : sheet ? ui.sheetSoft : ui.soft
  const press = sheet ? ui.sheetPress : ui.press
  return (
    <div
      look={primary ? 'primary' : on ? 'selected' : 'button'}
      className={`flex items-center justify-center gap-[${px(6)}] h-[${px(h)}] ${label ? `px-[${px(small ? 10 : 14)}]` : `w-[${px(h)}]`} rounded-[${px(10)}] ${grow ? 'flex-1 min-w-0' : 'shrink-0'} ${look} ${press}`}
      onClick={onClick}
    >
      {icon ? <Icon d={icon} size={Math.round(h * 0.5)} stroke /> : null}
      {label ? <span className={`text-[${px(small ? 13 : 15)}] font-bold whitespace-nowrap`}>{label}</span> : null}
    </div>
  )
}

// A thin bar that says how far: `share` from 0 to 1.
export function Meter({ ui, share, w, h, onSheet }) {
  const width = Math.max(1, Math.round(w))
  const done = Math.round(width * Math.max(0, Math.min(1, share || 0)))
  const height = Math.max(2, Math.round(h || 4 * Z.zoom))
  return (
    <div className={`relative w-[${raw(width)}] h-[${raw(height)}] rounded-full overflow-hidden ${onSheet ? `bg-[${ui.paperColor}] border border-[${ui.rule}]` : `bg-[${ui.track}] ${ui.trackBorder}`}`}>
      {done > 0 ? <div className={`absolute left-0 top-0 w-[${raw(done)}] h-full bg-[${onSheet ? ui.inkColor : ui.accentColor}]`} /> : null}
    </div>
  )
}

// ---- A paged list ----------------------------------------------------------------

// Rows into pages that fit `room` (the UI's pixels), each row its `height`:
// a heading never ends a page.
export function paginate(rows, room) {
  const pages = [[]]
  let used = 0
  rows.forEach((row, i) => {
    const next = rows[i + 1]
    const need = row.header && next ? row.height + next.height : row.height
    if (used + need > room && pages[pages.length - 1].length > 0) {
      pages.push([])
      used = 0
    }
    pages[pages.length - 1].push(row)
    used += row.height
  })
  return pages
}

export const pageOf = (pages, index) => Math.max(0, pages.findIndex((page) => page.some((row) => row.index === index)))
export const listRoom = (ui, extra) => ui.height / Z.zoom - 56 - 46 - (extra || 0)

// A paged list (the library, the contents, a catalog): rows, headings among
// them, arrows, and a highlight the keys move. A row's `index` is what onOpen
// gets. `tabs` is a row of buttons under the title bar.
export function Listing({ ui, title, pages: pageRows, page, sel, keys, onPage, onOpen, actions, empty, emptyAction, tabs, footer }) {
  const pages = Math.max(1, pageRows.length)
  const shown = pageRows[page] || []
  const rows = pageRows.flat()
  const arrow = `flex items-center justify-center w-[${px(40)}] h-[${px(34)}] rounded-[${px(8)}] ${ui.soft} ${ui.press}`
  return (
    <div look="page" className={`flex flex-col w-full h-full ${ui.bg} ${ui.text}`}>
      <div look="bar" className={`flex items-center gap-[${px(8)}] h-[${px(56)}] px-[${px(12)}] shrink-0`}>
        {title}
        {actions}
      </div>
      {tabs ? <div className={`flex items-center gap-[${px(6)}] h-[${px(40)}] px-[${px(12)}] shrink-0`}>{tabs}</div> : null}
      <div
        className={`flex flex-col flex-1 min-h-0 overflow-hidden px-[${px(12)}]`}
        onSwipe={
          rows.length === 0
            ? undefined
            : (e) => {
                if (e.direction === 'left' || e.direction === 'up') onPage(1)
                else if (e.direction === 'right' || e.direction === 'down') onPage(-1)
              }
        }
      >
        {rows.length === 0 ? (
          <div look="muted" className={`flex flex-col items-center justify-center flex-1 gap-[${px(10)}] px-[${px(24)}] ${ui.muted}`}>
            <Icon d={I.book} size={44} stroke width={1.6} />
            <span className={`text-[${px(16)}] text-center`}>{empty}</span>
            {emptyAction || null}
          </div>
        ) : (
          shown.map((row) => {
            if (row.header) {
              return (
                <div look="muted" className={`flex items-end h-[${px(row.height)}] px-[${px(10)}] pb-[${px(5)}] shrink-0 text-[${px(13)}] font-bold ${ui.muted}`}>
                  {row.label}
                </div>
              )
            }
            const lit = keys && row.index === sel
            return (
              <div
                look={lit ? 'selected' : 'option'}
                className={`flex items-center gap-[${px(12)}] h-[${px(row.height)}] px-[${px(10)}] shrink-0 ${ui.line} ${lit ? ui.accent : ui.press}`}
                onClick={() => onOpen(row.index)}
              >
                {row.thumb !== undefined ? (
                  row.thumb ? (
                    <img className={`w-[${raw(row.thumbW)}] h-[${raw(row.thumbH)}] shrink-0 object-cover`} src={row.thumb} />
                  ) : (
                    <div className={`flex items-center justify-center w-[${raw(row.thumbW)}] h-[${raw(row.thumbH)}] shrink-0 rounded-[${px(3)}] ${lit ? '' : ui.soft} ${lit ? '' : ui.muted}`}>
                      <Icon d={row.icon || I.book} size={Math.min(22, Math.round(row.thumbW / Z.zoom) - 10)} stroke width={1.8} />
                    </div>
                  )
                ) : row.icon ? (
                  <Icon d={row.icon} size={22} stroke width={row.iconWidth || 2} />
                ) : null}
                <div className={`flex flex-col justify-center gap-[${px(3)}] flex-1 min-w-0`}>
                  <span className={`text-[${px(row.sub ? 17 : 16)}] ${row.bold ? 'font-bold' : ''} truncate`}>{row.label}</span>
                  {row.sub ? (
                    <span look="muted" className={`text-[${px(13)}] ${lit ? '' : ui.muted} truncate`}>
                      {row.sub}
                    </span>
                  ) : null}
                  {row.share !== undefined && row.share > 0 ? <Meter ui={ui} share={row.share} w={Math.min(ui.width * 0.4, 220 * Z.zoom)} h={3 * Z.zoom} /> : null}
                </div>
                {row.right ? (
                  <span look="muted" className={`text-[${px(13)}] shrink-0 ${lit ? '' : ui.muted}`}>
                    {row.right}
                  </span>
                ) : null}
              </div>
            )
          })
        )}
      </div>
      <div className={`flex items-center gap-[${px(6)}] h-[${px(46)}] px-[${px(12)}] shrink-0`}>
        <div className={`flex items-center gap-[${px(6)}] flex-1 min-w-0`}>{footer || null}</div>
        {pages > 1
          ? [
              page > 0 ? (
                <div look="button" className={arrow} onClick={() => onPage(-1)}>
                  <Icon d={I.left} size={18} stroke width={2.8} />
                </div>
              ) : (
                <div className={`w-[${px(40)}] h-[${px(34)}]`} />
              ),
              <span look="muted" className={`w-[${px(72)}] text-center text-[${px(13)}] ${ui.muted}`}>{`${page + 1} of ${pages}`}</span>,
              page < pages - 1 ? (
                <div look="button" className={arrow} onClick={() => onPage(1)}>
                  <Icon d={I.right} size={18} stroke width={2.8} />
                </div>
              ) : (
                <div className={`w-[${px(40)}] h-[${px(34)}]`} />
              ),
            ]
          : null}
      </div>
    </div>
  )
}

// A title for a list's bar: a back arrow (or an icon), the title and a line
// under it.
export function Title({ ui, title, sub, onBack, icon }) {
  return [
    onBack ? (
      <div look="button" className={`flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] shrink-0 ${ui.soft} ${ui.press}`} onClick={onBack}>
        <Icon d={I.left} size={20} stroke width={2.8} />
      </div>
    ) : (
      <div look="accent" className={`flex items-center justify-center w-[${px(40)}] h-[${px(40)}] rounded-[${px(10)}] shrink-0 ${ui.accent}`}>
        <Icon d={icon || I.book} size={22} stroke width={2} />
      </div>
    ),
    <div className="flex flex-col flex-1 min-w-0">
      <span className={`text-[${px(19)}] font-bold truncate`}>{title}</span>
      {sub ? (
        <span look="muted" className={`text-[${px(13)}] ${ui.muted} truncate`}>
          {sub}
        </span>
      ) : null}
    </div>,
  ]
}

// A page of its own that is no list: a bar with a back arrow, and the body.
export function Page({ ui, title, sub, onBack, actions, children, footer }) {
  return (
    <div look="page" className={`flex flex-col w-full h-full ${ui.bg} ${ui.text}`}>
      <div look="bar" className={`flex items-center gap-[${px(8)}] h-[${px(56)}] px-[${px(12)}] shrink-0`}>
        <Title ui={ui} title={title} sub={sub} onBack={onBack} />
        {actions || null}
      </div>
      <div className={`flex flex-col flex-1 min-h-0 overflow-y-auto px-[${px(16)}] pb-[${px(10)}] gap-[${px(10)}]`}>{children}</div>
      {footer ? <div className={`flex items-center gap-[${px(8)}] px-[${px(12)}] py-[${px(8)}] shrink-0`}>{footer}</div> : null}
    </div>
  )
}

// A time span said briefly: "45 s", "12 min", "3 h 20 min".
export function duration(seconds) {
  const s = Math.max(0, Math.round(seconds || 0))
  if (s < 60) return `${s} s`
  const m = Math.round(s / 60)
  if (m < 60) return `${m} min`
  const h = Math.floor(m / 60)
  const rest = m - h * 60
  return rest ? `${h} h ${rest} min` : `${h} h`
}

// "today", "yesterday", "3 days ago", or the date.
export function ago(ms, now) {
  if (!ms) return ''
  const days = Math.floor((startOfDay(now) - startOfDay(ms)) / 86400000)
  if (days <= 0) return 'today'
  if (days === 1) return 'yesterday'
  if (days < 7) return `${days} days ago`
  const d = new Date(ms)
  return `${d.getDate()} ${MONTHS[d.getMonth()]}${d.getFullYear() !== new Date(now).getFullYear() ? ' ' + d.getFullYear() : ''}`
}

export const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

export function startOfDay(ms) {
  const d = new Date(ms)
  d.setHours(0, 0, 0, 0)
  return d.getTime()
}

export function sizeText(bytes) {
  if (!bytes && bytes !== 0) return ''
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`
  return `${(bytes / 1048576).toFixed(bytes < 10485760 ? 1 : 0)} MB`
}

sources.epub.ts:
// An EPUB on the frame's card: its package (title, author, cover, chapters in
// order), its contents, its chapters as blocks of text, its pictures.
//
// An EPUB is a ZIP of XHTML chapters. frameos.readAsset reads one member of it
// ({ entry }) inflated by the runtime, as text, so a chapter costs its own
// size and never the book's. How big each chapter is comes from the ZIP's own
// directory, read once (zipSizes): that is what "how far through the book"
// and "how long it has left" are measured in.

// ---- Where a book is -------------------------------------------------------------

// A book is "<storage>:<path>": which of app.frame.storages it is in (the TF
// card's "assets", "internal") and its path there. A key from before storages
// (a bare path) was in the assets folder, which on an ESP32 with no card is
// its internal storage: normalKey says which, by the storages listed.
export const STORAGE_IDS = ['assets', 'internal']
export function placeOf(key) {
  const at = key.indexOf(':')
  const storage = at > 0 ? key.slice(0, at) : ''
  return STORAGE_IDS.includes(storage) ? { storage, path: key.slice(at + 1) } : { storage: 'assets', path: key }
}
export const keyOf = (storage, path) => `${storage}:${path}`
export function normalKey(key, storages) {
  if (typeof key !== 'string' || !key) return key
  const at = key.indexOf(':')
  if (at > 0 && STORAGE_IDS.includes(key.slice(0, at))) return key
  const home = storages.some((s) => s.id === 'assets') ? 'assets' : storages[0].id
  return keyOf(home, key)
}
export const baseName = (path) => path.split('/').pop()
export const bookName = (key) => baseName(placeOf(key).path).replace(/\.epub$/i, '').replace(/[_]+/g, ' ')

// Where the asset calls reach (FrameOS 2026.11.11+), and before that the one
// assets folder.
export function storagesOf(app) {
  const storages = Array.isArray(app.frame.storages) ? app.frame.storages.filter((s) => s && STORAGE_IDS.includes(s.id)) : []
  return storages.length > 0 ? storages : [{ id: 'assets', name: 'Internal storage' }]
}

// ---- Text out of XHTML -------------------------------------------------------

const ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: '\u00a0', mdash: '\u2014', ndash: '\u2013',
  hellip: '\u2026', lsquo: '\u2018', rsquo: '\u2019', ldquo: '\u201c', rdquo: '\u201d', laquo: '\u00ab',
  raquo: '\u00bb', copy: '\u00a9', reg: '\u00ae', trade: '\u2122', shy: '', thinsp: ' ', ensp: ' ', emsp: ' ',
  bull: '\u2022', middot: '\u00b7', eacute: '\u00e9', egrave: '\u00e8', aacute: '\u00e1', agrave: '\u00e0',
  ouml: '\u00f6', uuml: '\u00fc', auml: '\u00e4', szlig: '\u00df', ccedil: '\u00e7', iacute: '\u00ed',
  oacute: '\u00f3', uacute: '\u00fa', ntilde: '\u00f1', deg: '\u00b0', times: '\u00d7', frac12: '\u00bd',
}

export function decode(text) {
  return text.replace(/&(#[xX][0-9a-fA-F]+|#\d+|[a-zA-Z]+\d*);/g, (all, name) => {
    if (name[0] === '#') {
      const code = name[1] === 'x' || name[1] === 'X' ? parseInt(name.slice(2), 16) : parseInt(name.slice(1), 10)
      return code > 0 && code < 0x110000 ? String.fromCodePoint(code) : ''
    }
    const named = ENTITIES[name]
    return named === undefined ? all : named
  })
}

export const clean = (text) =>
  decode(String(text || '').replace(/<[^>]*>/g, ''))
    .replace(/[\u00ad\u200b\u200c\u200d\ufeff]/g, '')
    .replace(/[ \t\r\n\f]+/g, ' ')
    .trim()

// An SVG in the book's XHTML and the image element in it. The patterns are
// built from their names: the scene linter reads those tags written out in an
// app's source as an SVG the app draws, which these are not.
const SVG_NAME = 'svg'
const IMAGE_NAME = 'image'
const SVG_BLOCK = new RegExp(`<${SVG_NAME}\\b[\\s\\S]*?</${SVG_NAME}\\s*>`, 'gi')
const SVG_IMAGE = new RegExp(`<${IMAGE_NAME}\\b[^>]*>`, 'i')

// The pictures the frame decodes (no SVG: a book's are its covers, made <img> above).
export const PICTURES = /\.(jpe?g|png|gif|webp|bmp)$/i

const BLOCK_TAGS = new Set([
  'p', 'div', 'section', 'article', 'header', 'footer', 'aside', 'main', 'nav', 'figure', 'figcaption',
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'li', 'ul', 'ol', 'dl', 'dt', 'dd', 'blockquote', 'pre', 'table',
  'tr', 'td', 'th', 'caption', 'body', 'center', 'address', 'hgroup',
])

// A chapter's text as blocks: { k: kind, t: text, ni: no first-line indent },
// and its pictures as { k: 'img', src: the member's path, alt }. base is the
// chapter's folder in the book, which a picture's src is relative to.
export function parseChapter(xhtml, base) {
  let s = xhtml
  const body = s.search(/<body[\s>]/i)
  if (body >= 0) s = s.slice(body)
  s = s
    .replace(/<!--[\s\S]*?-->|<\?[\s\S]*?\?>|<![^>]*>/g, ' ')
    // A picture drawn as an SVG image element (many covers) is a picture
    // like <img>.
    .replace(SVG_BLOCK, (svg) => {
      const image = SVG_IMAGE.exec(svg)
      const href = image && (attrOf(image[0], 'xlink:href') || attrOf(image[0], 'href'))
      return href ? `<img src="${href.replace(/"/g, '&quot;')}"/>` : ' '
    })
    .replace(/<(script|style|head)\b[\s\S]*?<\/\1\s*>/gi, ' ')
  const blocks = []
  let text = ''
  let kind = 'p'
  let quotes = 0
  let heads = 0 // inside an <hgroup>: its <p> (a chapter's title under its number) is a heading
  let broke = false
  const lists = [] // the open lists: 0 for a bulleted one, else the next number
  let marker = '' // a list item's bullet or number, waiting for its text
  const flush = () => {
    const t = text.includes('&') ? decode(text) : text
    let tidy = t.replace(/[\u00ad\u200b\u200c\u200d\ufeff]/g, '').replace(/[ \t\r\n\f]+/g, ' ').trim()
    text = ''
    if (/^(\u2022|\d+\.)$/.test(tidy)) {
      // An item whose text is in a block of its own (<li><p>…</p></li>).
      marker = tidy + ' '
      return
    }
    let k = kind
    if (tidy && marker) {
      tidy = marker + tidy
      marker = ''
      k = 'li'
    }
    if (tidy) blocks.push(broke ? { k, t: tidy, ni: true } : { k, t: tidy })
    broke = false
  }
  const re = /<(\/?)([a-zA-Z][\w:.-]*)([^>]*?)(\/?)>|([^<]+)|</g
  let m
  while ((m = re.exec(s))) {
    if (m[5] !== undefined) {
      text += m[5]
      continue
    }
    if (m[2] === undefined) {
      text += '<'
      continue
    }
    const tag = m[2].toLowerCase()
    const closing = m[1] === '/'
    if (tag === 'br') {
      const k = kind
      flush()
      kind = k
      broke = true
      continue
    }
    if (tag === 'hr') {
      flush()
      blocks.push({ k: 'hr', t: '' })
      continue
    }
    if (tag === 'img' && !closing) {
      const src = attrOf(' ' + m[3], 'src')
      if (src && PICTURES.test(src.split(/[?#]/)[0])) {
        const k = kind
        flush()
        kind = k
        blocks.push({ k: 'img', t: '', src: resolve(base || '', src), alt: clean(attrOf(' ' + m[3], 'alt') || '') })
      }
      continue
    }
    if (!BLOCK_TAGS.has(tag)) {
      // Inline: a space where a word ends at the tag is the text's own.
      continue
    }
    flush()
    if (tag === 'blockquote') quotes = Math.max(0, quotes + (closing ? -1 : 1))
    if (tag === 'hgroup') heads = Math.max(0, heads + (closing ? -1 : 1))
    if (tag === 'ul' || tag === 'ol') {
      if (closing) lists.pop()
      else if (m[4] !== '/') lists.push(tag === 'ol' ? 1 : 0)
    }
    const plain = quotes > 0 ? 'q' : 'p'
    if (closing || m[4] === '/') kind = plain
    else if (tag === 'h1' || tag === 'h2') kind = 'h'
    else if (tag === 'h3' || tag === 'h4' || tag === 'h5' || tag === 'h6') kind = 'h3'
    else if (tag === 'li') {
      kind = 'li'
      const n = lists.length > 0 ? lists[lists.length - 1] : 0
      text = n > 0 ? `${n}. ` : '\u2022 '
      if (n > 0) lists[lists.length - 1] = n + 1
    } else if (tag === 'dd') kind = 'li'
    else kind = heads > 0 && tag === 'p' ? 'h3' : plain
  }
  flush()
  return blocks
}

// ---- The book: container, package, contents ---------------------------------

export function attrOf(tag, name) {
  const m = new RegExp('\\s' + name.replace(/[:]/g, '\\:') + '\\s*=\\s*("([^"]*)"|\'([^\']*)\')', 'i').exec(tag)
  return m ? decode(m[2] !== undefined ? m[2] : m[3]) : null
}

export const dirOf = (path) => (path.includes('/') ? path.slice(0, path.lastIndexOf('/') + 1) : '')

export function resolve(base, href) {
  let path = href.split('#')[0]
  try {
    path = decodeURIComponent(path)
  } catch (e) {}
  const parts = (path.startsWith('/') ? path.slice(1) : base + path).split('/')
  const out = []
  for (const part of parts) {
    if (part === '..') out.pop()
    else if (part !== '.' && part !== '') out.push(part)
  }
  return out.join('/')
}

export function readEntry(key, entry, offset, length) {
  const at = placeOf(key)
  return frameos.readAsset(at.path, { entry, text: true, offset: offset || 0, length: length || 1024 * 1024, storage: at.storage })
}

// The package: where the chapters are, in order, and what the book is called.
export function readPackage(path) {
  const container = readEntry(path, 'META-INF/container.xml')
  if (!container) return { error: 'This is not an EPUB book.' }
  const rootfile = /<rootfile\b[^>]*>/i.exec(container)
  const opfPath = rootfile && attrOf(rootfile[0], 'full-path')
  const opf = opfPath ? readEntry(path, opfPath) : null
  if (!opf) return { error: 'The book has no table of its chapters.' }
  const base = dirOf(opfPath)
  const items = {}
  let nav = null
  let ncx = null
  let cover = null
  for (const m of opf.match(/<(?:\w+:)?item\b[^>]*>/gi) || []) {
    const id = attrOf(m, 'id')
    const href = attrOf(m, 'href')
    if (!id || !href) continue
    const type = attrOf(m, 'media-type') || ''
    const item = { href: resolve(base, href), type }
    items[id] = item
    const props = attrOf(m, 'properties') || ''
    if (/(^|\s)nav(\s|$)/.test(props)) nav = item.href
    if (/(^|\s)cover-image(\s|$)/.test(props)) cover = item.href
    if (type === 'application/x-dtbncx+xml') ncx = ncx || item.href
  }
  const spine = []
  const spineTag = /<(?:\w+:)?spine\b[^>]*>/i.exec(opf)
  const tocId = spineTag && attrOf(spineTag[0], 'toc')
  if (tocId && items[tocId]) ncx = items[tocId].href
  for (const m of opf.match(/<(?:\w+:)?itemref\b[^>]*>/gi) || []) {
    const item = items[attrOf(m, 'idref')]
    if (!item || attrOf(m, 'linear') === 'no') continue
    if (item.type && !/html|xml/.test(item.type)) continue
    spine.push(item.href)
  }
  if (spine.length === 0) return { error: 'The book has no chapters.' }
  const meta = (tag) => {
    const m = new RegExp('<(?:dc:)?' + tag + '\\b[^>]*>([\\s\\S]*?)</(?:dc:)?' + tag + '>', 'i').exec(opf)
    return m ? clean(m[1]) : ''
  }
  // An EPUB 2 names its cover in <meta name="cover" content="the item's id">.
  if (!cover) {
    const named = /<meta\b[^>]*\bname\s*=\s*["']cover["'][^>]*>/i.exec(opf)
    const item = named && items[attrOf(named[0], 'content')]
    if (item && PICTURES.test(item.href)) cover = item.href
  }
  return {
    title: meta('title') || bookName(path),
    author: meta('creator'),
    language: meta('language'),
    spine,
    nav,
    ncx,
    cover,
  }
}

// The contents, as { label, s } with s the chapter in the spine it opens.
export function readContents(path, pkg) {
  const toc = []
  const place = (file, href, label) => {
    const target = resolve(dirOf(file), href)
    const s = pkg.spine.indexOf(target)
    if (s >= 0 && label && !toc.some((entry) => entry.s === s)) toc.push({ label, s })
  }
  if (pkg.nav) {
    const doc = readEntry(path, pkg.nav)
    if (doc) {
      const start = doc.search(/<nav\b[^>]*epub:type\s*=\s*["'][^"']*\btoc\b/i)
      const from = start >= 0 ? start : doc.search(/<nav\b/i)
      const part = from >= 0 ? doc.slice(from, doc.indexOf('</nav>', from) + 6 || undefined) : doc
      const re = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi
      let m
      while ((m = re.exec(part))) {
        const href = attrOf(m[1] ? ' ' + m[1] : '', 'href')
        if (href) place(pkg.nav, href, clean(m[2]))
      }
    }
  }
  if (toc.length === 0 && pkg.ncx) {
    const doc = readEntry(path, pkg.ncx)
    if (doc) {
      const re = /<navPoint\b[\s\S]*?<text>([\s\S]*?)<\/text>[\s\S]*?<content\b([^>]*)>/gi
      let m
      while ((m = re.exec(doc))) {
        const href = attrOf(' ' + m[2], 'src')
        if (href) place(pkg.ncx, href, clean(m[1]))
      }
    }
  }
  toc.sort((a, b) => a.s - b.s)
  return toc
}

// ---- The ZIP's directory: how big each chapter is ---------------------------------

// Every member's uncompressed size, by name, from the ZIP's central directory
// at the end of the file: two reads, whatever the book's size. Null when the
// file is no ZIP the frame can read this way (ZIP64, a damaged end).
export function zipSizes(key) {
  const at = placeOf(key)
  const options = { storage: at.storage }
  let size = 0
  try {
    size = frameos.assetSize(at.path, options)
  } catch (e) {
    size = 0
  }
  if (!(size > 22)) return null
  const tailLength = Math.min(size, 22 + 65535)
  const tail = frameos.readAsset(at.path, { offset: size - tailLength, length: tailLength, bytes: true, storage: at.storage })
  if (!tail || !tail.length) return null
  let end = -1
  for (let i = tail.length - 22; i >= 0; i--) {
    if (tail[i] === 0x50 && tail[i + 1] === 0x4b && tail[i + 2] === 0x05 && tail[i + 3] === 0x06) {
      end = i
      break
    }
  }
  if (end < 0) return null
  const u16 = (b, i) => b[i] | (b[i + 1] << 8)
  const u32 = (b, i) => (b[i] | (b[i + 1] << 8) | (b[i + 2] << 16)) + b[i + 3] * 16777216
  const count = u16(tail, end + 10)
  const cdSize = u32(tail, end + 12)
  const cdOffset = u32(tail, end + 16)
  if (cdOffset === 0xffffffff || cdSize > 4 * 1024 * 1024 || cdOffset + cdSize > size) return null
  const cd = frameos.readAsset(at.path, { offset: cdOffset, length: cdSize, bytes: true, storage: at.storage })
  if (!cd || cd.length < cdSize) return null
  const sizes = {}
  let i = 0
  for (let n = 0; n < count && i + 46 <= cd.length; n++) {
    if (u32(cd, i) !== 0x02014b50) break
    const raw = u32(cd, i + 24)
    const nameLength = u16(cd, i + 28)
    const extra = u16(cd, i + 30)
    const comment = u16(cd, i + 32)
    let name = ''
    for (let k = 0; k < nameLength; k++) name += String.fromCharCode(cd[i + 46 + k])
    try {
      name = decodeURIComponent(escape(name))
    } catch (e) {}
    sizes[name] = raw
    i += 46 + nameLength + extra + comment
  }
  return sizes
}

// ---- What a book is while it is open ---------------------------------------------

// What lives only as long as the interpreter: the book open, the chapter
// parsed. `remember` keeps the book across a frame's sleep.
let opened = null // { path, title, author, cover, spine, toc, w }
let loaded = { key: '', blocks: [], more: false, chars: 0 }

export function openBook(path) {
  if (opened && opened.path === path) return opened
  const kept = frameos.recall('book')
  if (kept && typeof kept === 'object' && kept.path === path && Array.isArray(kept.spine) && Array.isArray(kept.w)) {
    opened = kept
    return opened
  }
  const pkg = readPackage(path)
  if (pkg.error) return { path, error: pkg.error }
  // Each chapter's weight: its XHTML's size, at least one.
  const sizes = zipSizes(path)
  const w = pkg.spine.map((member) => Math.max(1, (sizes && sizes[member]) || 0))
  const even = !sizes || w.every((x) => x === 1)
  opened = {
    path,
    title: pkg.title,
    author: pkg.author,
    language: pkg.language,
    cover: pkg.cover,
    spine: pkg.spine,
    toc: readContents(path, pkg),
    w: even ? pkg.spine.map(() => 10000) : w,
  }
  frameos.remember('book', opened)
  return opened
}

export function forgetBook() {
  opened = null
  loaded = { key: '', blocks: [], more: false, chars: 0 }
}

// ---- Chapters, in parts the frame can hold -----------------------------------

// A part of a chapter is this many bytes of its XHTML: a chapter longer than
// that (a whole book in one file) is read a part at a time.
export const partBytes = (ui) => (ui.embedded ? 256 * 1024 : 2 * 1024 * 1024)
export const partsOf = (book, s, ui) => Math.max(1, Math.ceil(book.w[s] / partBytes(ui)))

function utf8Length(text) {
  try {
    return unescape(encodeURIComponent(text)).length
  } catch (e) {
    return text.length * 3
  }
}

export function chapterOf(book, s, p, ui) {
  const key = `${book.path}|${s}|${p}`
  if (loaded.key === key) return loaded
  const size = partBytes(ui)
  let text = readEntry(book.path, book.spine[s], p * size, size) || ''
  // Whether the chapter goes on past this part: only a part read whole can.
  const more = text.length * 3 >= size - 8 && utf8Length(text) >= size - 8
  // A tag cut at either end of a part is left out.
  if (p > 0) {
    const close = text.indexOf('>')
    const open = text.indexOf('<')
    if (close >= 0 && (open < 0 || close < open)) text = text.slice(close + 1)
  }
  if (more) {
    const open = text.lastIndexOf('<')
    if (open >= 0 && text.indexOf('>', open) < 0) text = text.slice(0, open)
  }
  // Pictures the book does not hold, or the frame cannot read, are left out;
  // one alone on its page (a cover, a plate) fills the page.
  const blocks = parseChapter(text, dirOf(book.spine[s])).filter((block) => block.k !== 'img' || pictureSize(book.path, block.src))
  if (blocks.length === 1 && blocks[0].k === 'img') blocks[0].alone = true
  let chars = 0
  for (const block of blocks) chars += block.t.length + 1
  loaded = { key, blocks, more, chars }
  return loaded
}

// ---- Pictures ------------------------------------------------------------------

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
const B64_INDEX = {}
for (let i = 0; i < 64; i++) B64_INDEX[B64[i]] = i

function bytesOf(base64) {
  const text = base64.replace(/[^A-Za-z0-9+/]/g, '')
  const out = new Uint8Array(Math.floor((text.length * 3) / 4))
  let o = 0
  for (let i = 0; i + 1 < text.length; i += 4) {
    const n = (B64_INDEX[text[i]] << 18) | (B64_INDEX[text[i + 1]] << 12) | ((B64_INDEX[text[i + 2]] || 0) << 6) | (B64_INDEX[text[i + 3]] || 0)
    out[o++] = (n >> 16) & 255
    if (i + 2 < text.length) out[o++] = (n >> 8) & 255
    if (i + 3 < text.length) out[o++] = n & 255
  }
  return out.subarray(0, o)
}

// A picture's width and height off its header, without decoding it: what a
// page needs to know to lay it out. null when it is no picture the frame reads.
const pictureSizes = new Map() // book path | member -> [w, h] | null

export function pictureSize(path, src) {
  const key = `${path}|${src}`
  if (pictureSizes.has(key)) return pictureSizes.get(key)
  let size = null
  const at = placeOf(path)
  const head = (length) => bytesOf(frameos.readAsset(at.path, { entry: src, length, storage: at.storage }) || '')
  try {
    let b = head(64)
    const be16 = (i) => (b[i] << 8) | b[i + 1]
    const be32 = (i) => ((b[i] << 24) >>> 0) + (b[i + 1] << 16) + (b[i + 2] << 8) + b[i + 3]
    const le16 = (i) => b[i] | (b[i + 1] << 8)
    const le24 = (i) => b[i] | (b[i + 1] << 8) | (b[i + 2] << 16)
    if (b.length >= 24 && b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) {
      size = [be32(16), be32(20)]
    } else if (b.length >= 10 && b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46) {
      size = [le16(6), le16(8)]
    } else if (b.length >= 26 && b[0] === 0x42 && b[1] === 0x4d) {
      size = [Math.abs(le24(18) | (b[21] << 24)), Math.abs(le24(22) | (b[25] << 24))]
    } else if (b.length >= 30 && b[0] === 0x52 && b[8] === 0x57 && b[9] === 0x45) {
      const kind = String.fromCharCode(b[12], b[13], b[14], b[15])
      if (kind === 'VP8X') size = [1 + le24(24), 1 + le24(27)]
      else if (kind === 'VP8 ') size = [le16(26) & 0x3fff, le16(28) & 0x3fff]
      else if (kind === 'VP8L') size = [1 + (((b[22] & 0x3f) << 8) | b[21]), 1 + (((b[24] & 0xf) << 10) | (b[23] << 2) | ((b[22] & 0xc0) >> 6))]
    } else if (b.length >= 4 && b[0] === 0xff && b[1] === 0xd8) {
      // A JPEG says its size in its frame header, after whatever comes first
      // (EXIF, a thumbnail): its markers walked, in the first 64 KB.
      b = head(64 * 1024)
      let i = 2
      while (i + 9 < b.length) {
        if (b[i] !== 0xff) {
          i++
          continue
        }
        const marker = b[i + 1]
        if (marker === 0xff) {
          i++
          continue
        }
        if (marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
          i += 2
          continue
        }
        if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
          size = [be16(i + 7), be16(i + 5)]
          break
        }
        i += 2 + be16(i + 2)
      }
    }
  } catch (e) {
    size = null
  }
  if (size && !(size[0] > 0 && size[1] > 0)) size = null
  pictureSizes.set(key, size)
  return size
}

// Decoded pictures kept between renders, at the size they are drawn. Only
// what the view shows is kept: the frame holds 8 big ones at most.
let pictures = new Map() // key -> image ref

export function picturesFor(wanted, background) {
  const next = new Map()
  for (const [key, ref] of pictures) {
    if (wanted.some((want) => want.key === key)) next.set(key, ref)
    else if (ref) frameos.releaseImage(ref)
  }
  for (const want of wanted) {
    if (next.has(want.key)) continue
    const at = placeOf(want.path)
    const ref = frameos.loadAssetImage(at.path, {
      entry: want.src,
      width: want.w,
      height: want.h,
      fit: want.fit || 'contain',
      keep: true,
      background,
      storage: at.storage,
    })
    next.set(want.key, ref || null)
  }
  pictures = next
  return pictures
}

