// Blocks into pages. Each line is measured with the advance widths of the
// frame's face (Ubuntu), so a page holds exactly what fits, at any text size,
// line spacing and margin, in one column or two on a wide screen. A page is
// where it starts ([block, char]) in a chapter's part; the starts of the pages
// read so far are kept, so a page back is never laid out again.

import { Z } from './ui'
import { chapterOf, partsOf, pictureSize } from './epub'

export const SIZES = [16, 18, 20, 22, 24, 26, 29, 32, 36, 40, 46]
export const DEFAULT_SIZE = 5
export const SPACINGS = [1.22, 1.42, 1.7]
export const MARGINS = [0.55, 1, 1.7]

// Advance widths of U+0020..U+017F in hundredths of an em, two digits each:
// Ubuntu Regular, the face every frame draws text in (00 = no glyph).
const WIDTHS = ''
const PUNCT = { 0x2013: 50, 0x2014: 100, 0x2015: 100, 0x2018: 24, 0x2019: 24, 0x201a: 24, 0x201c: 42, 0x201d: 42, 0x201e: 42, 0x2020: 48, 0x2021: 48, 0x2022: 36, 0x2026: 100, 0x2042: 100 }
const advance = []
for (let i = 0; i < 352; i++) advance.push(parseInt(WIDTHS.slice(i * 2, i * 2 + 2), 10) || 0)

export function widthOf(code) {
  if (code >= 32 && code < 384) return advance[code - 32] || 58
  const p = PUNCT[code]
  if (p) return p
  if (code >= 0x2e80) return 100 // CJK and the like: an em
  return 58
}

export function textWidth(text, from, to, unit) {
  let sum = 0
  for (let i = from; i < to; i++) sum += widthOf(text.charCodeAt(i))
  return sum * unit
}

// How each kind of block is set: size against the body text, bold, the room
// above and below in lines, the left inset in ems.
const STYLES = {
  h: { scale: 1.35, bold: true, before: 1, after: 0.5, left: 0 },
  h3: { scale: 1.12, bold: true, before: 0.8, after: 0.3, left: 0 },
  p: { scale: 1, bold: false, before: 0, after: 0, left: 0 },
  li: { scale: 1, bold: false, before: 0.15, after: 0.15, left: 1 },
  q: { scale: 1, bold: false, before: 0.3, after: 0.3, left: 1.5 },
  hr: { scale: 1, bold: false, before: 0.3, after: 0.3, left: 0 },
}

export const isHeading = (block) => block.k === 'h' || block.k === 'h3'
export const before = (a, b) => a[0] < b[0] || (a[0] === b[0] && a[1] < b[1])

// The reading settings, with what an older spot had.
export function prefsOf(spot) {
  const p = spot.prefs && typeof spot.prefs === 'object' ? spot.prefs : {}
  const size = Number.isInteger(p.size) ? p.size : Number.isInteger(spot.size) ? spot.size + 1 : DEFAULT_SIZE
  return {
    size: Math.max(0, Math.min(SIZES.length - 1, size)),
    spacing: [0, 1, 2].includes(p.spacing) ? p.spacing : 1,
    margin: [0, 1, 2].includes(p.margin) ? p.margin : 1,
    justify: p.justify === true,
    theme: ['light', 'sepia', 'dark'].includes(p.theme) ? p.theme : 'light',
    status: ['full', 'bar', 'none'].includes(p.status) ? p.status : 'full',
    columns: p.columns === 1 ? 1 : 0,
  }
}

export function geometry(ui, prefs, book) {
  const zoom = Z.zoom
  const fs = Math.round(SIZES[prefs.size] * zoom)
  const lh = Math.round(fs * SPACINGS[prefs.spacing])
  const margin = Math.round(Math.max(14, Math.min(64, (ui.width / zoom / 22) * MARGINS[prefs.margin])) * zoom)
  const bar = Math.round(34 * zoom)
  const foot = prefs.status === 'none' ? Math.round(14 * zoom) : prefs.status === 'bar' ? Math.round(18 * zoom) : bar
  // Two columns when one would run past about 80 characters a line (an
  // average character is half an em), so each still holds 40.
  const cols = prefs.columns !== 1 && (ui.width - margin * 2) / (fs * 0.5) > 80 ? 2 : 1
  const gap = Math.round(56 * zoom)
  const w = Math.floor((ui.width - margin * 2 - gap * (cols - 1)) / cols)
  const room = ui.height - bar - foot - Math.round(12 * zoom)
  // Whole lines of body text: the page's room rounded down to them.
  const h = Math.max(lh, Math.floor(room / lh) * lh)
  const sizeOf = (src) => pictureSize(book.path, src)
  const key = `${fs}|${lh}|${w}|${h}|${cols}`
  return { fs, lh, margin, bar, foot, cols, gap, w, h, top: bar + Math.round((room - h) / 2) + Math.round(6 * zoom), sizeOf, key }
}

// Where the line that starts at `from` ends: after the last space (or dash)
// that fits, or inside a word longer than the line.
function breakLine(text, from, width, unit) {
  let sum = 0
  let space = -1
  const limit = width * 0.985
  for (let i = from; i < text.length; i++) {
    const code = text.charCodeAt(i)
    if (code === 32) space = i
    sum += widthOf(code) * unit
    if (sum > limit) {
      if (space > from) return space
      return Math.max(from + 1, i)
    }
    if ((code === 45 || code === 0x2014 || code === 0x2013) && i > from) space = i + 1
  }
  return text.length
}

// One page from `start` ([block, char]): its lines, and where the next page
// starts (null at the end of the chapter's part). A text line says which
// block it is (b), the characters it shows (c to e), its unit (the width of
// a hundredth of an em) and whether it may be justified (j: not a block's
// last line).
export function layoutPage(blocks, start, g) {
  const lines = []
  let y = 0
  let b = start[0]
  let c = start[1]
  while (b < blocks.length) {
    const block = blocks[b]
    const style = STYLES[block.k] || STYLES.p
    const fs = Math.round(g.fs * style.scale)
    const lh = Math.round(g.lh * style.scale)
    // A heading under a heading (a chapter's title under its number) sits
    // close to it; a line after a <br/> goes on the block before it.
    const prior = b > 0 ? blocks[b - 1] : null
    const stacked = isHeading(block) && prior && isHeading(prior)
    const room = c === 0 && lines.length > 0 && !block.ni ? Math.round((stacked ? 0.15 : style.before) * g.lh) : 0
    const left = Math.round(style.left * g.fs)
    if (block.k === 'img') {
      // As wide as the picture is (in the UI's pixels), at most the column
      // and the page; on the next page when it does not fit under the text.
      const size = g.sizeOf(block.src)
      if (size) {
        let w = block.alone ? g.w : Math.min(g.w, Math.round(size[0] * Z.zoom))
        let h = Math.round((w * size[1]) / size[0])
        if (h > g.h) {
          h = g.h
          w = Math.max(1, Math.round((h * size[0]) / size[1]))
        }
        const gap = Math.round(0.4 * g.lh)
        const top = lines.length > 0 ? y + gap : y
        if (lines.length > 0 && top + h > g.h) return { lines, next: [b, 0] }
        if (w >= 4 && h >= 4) {
          lines.push({ img: block.src, alt: block.alt, b, x: Math.round((g.w - w) / 2), y: top, w, h })
          y = top + h + gap
        }
      }
      b++
      c = 0
      continue
    }
    if (block.k === 'hr') {
      if (lines.length > 0 && y + room + lh > g.h) return { lines, next: [b, 0] }
      lines.push({ hr: true, b, y: y + room, lh })
      y += room + lh + Math.round(style.after * g.lh)
      b++
      c = 0
      continue
    }
    const prev = b > 0 ? blocks[b - 1] : null
    const indent = block.k === 'p' && !block.ni && prev && prev.k === 'p' ? Math.round(g.fs * 1.4) : 0
    const unit = (fs / 100) * (style.bold ? 1.07 : 1)
    let first = true
    while (c < block.t.length) {
      const top = y + (first ? room : 0)
      if (lines.length > 0 && top + lh > g.h) return { lines, next: [b, c] }
      const inset = left + (c === 0 ? indent : 0)
      const end = breakLine(block.t, c, g.w - inset, unit)
      // The characters shown, without the spaces at either end.
      let e = end
      while (e > c && block.t.charCodeAt(e - 1) === 32) e--
      let from = c
      while (from < e && block.t.charCodeAt(from) === 32) from++
      let next = end
      while (block.t.charCodeAt(next) === 32) next++
      const j = next < block.t.length && !isHeading(block)
      lines.push({ t: block.t.slice(from, e), b, c: from, e, x: inset, y: top, fs, lh, bold: style.bold, unit, w: g.w - inset, j })
      y = top + lh
      first = false
      c = next
    }
    const following = blocks[b + 1]
    if (!(following && (following.ni || (isHeading(block) && isHeading(following))))) y += Math.round(style.after * g.lh)
    b++
    c = 0
  }
  return { lines, next: null }
}

// The words of a justified line and where each starts, left to right: the
// space between them shared out as `flex justify-between` shares it.
export function justified(line) {
  const words = []
  const re = /\S+/g
  let m
  let natural = 0
  while ((m = re.exec(line.t))) {
    const w = textWidth(line.t, m.index, m.index + m[0].length, line.unit)
    words.push({ t: m[0], from: line.c + m.index, to: line.c + m.index + m[0].length, w })
    natural += w
  }
  const gap = words.length > 1 ? Math.max(0, (line.w - natural) / (words.length - 1)) : 0
  let x = 0
  for (const word of words) {
    word.x = x
    x += word.w + gap
  }
  return words
}

// Where character `at` of a line begins, from the line's left.
export function xOf(line, at, justify) {
  const k = Math.max(line.c, Math.min(line.e, at))
  if (justify && line.j) {
    for (const word of justified(line)) {
      if (k <= word.to) return word.x + (k <= word.from ? 0 : textWidth(line.t, word.from - line.c, k - line.c, line.unit))
    }
    return line.w
  }
  return textWidth(line.t, 0, k - line.c, line.unit)
}

// The character of a line under x (from the line's left).
function charAt(line, x, justify) {
  for (let k = line.c; k < line.e; k++) {
    const right = xOf(line, k + 1, justify)
    if (right > x) return k
  }
  return Math.max(line.c, line.e - 1)
}

// The word under (x, y) of a spread (x, y from the page area's corner), as
// [block, first char, end char], or null.
export function wordAt(pages, g, x, y, justify, text) {
  for (let k = 0; k < pages.length; k++) {
    const left = g.margin + k * (g.w + g.gap)
    if (x < left - g.gap / 2 || x > left + g.w + g.gap / 2) continue
    let best = null
    for (const line of pages[k].lines) {
      if (line.t === undefined) continue
      const top = g.top + line.y
      if (y >= top - line.lh * 0.25 && y < top + line.lh * 1.1) {
        best = line
        if (y < top + line.lh) break
      }
    }
    if (!best) return null
    const t = text(best.b)
    let at = charAt(best, x - left - best.x, justify)
    let from = at
    let to = at
    while (from > 0 && /\S/.test(t[from - 1])) from--
    while (to < t.length && /\S/.test(t[to])) to++
    if (to === from) to = Math.min(t.length, from + 1)
    return [best.b, from, to]
  }
  return null
}

// ---- Moving through the book ---------------------------------------------------

// The pages of the chapter part `at` is in, as far as they are known, and
// which spread shows: kept in the spot, so a page back costs nothing.
export function pagesFor(spot, book, at, g, ui) {
  const chapter = chapterOf(book, at.s, at.p, ui)
  const key = `${book.path}|${at.s}|${at.p}|${g.key}`
  let pg = spot.pg
  if (!pg || pg.key !== key || !Array.isArray(pg.starts)) {
    pg = { key, starts: [[0, 0]], i: 0 }
    const target = [at.b || 0, at.c || 0]
    for (let guard = 0; guard < 5000; guard++) {
      const next = layoutPage(chapter.blocks, pg.starts[pg.starts.length - 1], g).next
      if (!next || before(target, next)) break
      pg.starts.push(next)
    }
    pg.i = pg.starts.length - 1
    pg.i -= pg.i % g.cols
  }
  spot.pg = pg
  return { chapter, pg }
}

// The spread showing: each page's lines, and where the spread ends.
export function spreadOf(spot, book, g, ui) {
  const { chapter, pg } = pagesFor(spot, book, spot.at, g, ui)
  // The place is where its page starts (a jump lands inside a page).
  const first = pg.starts[pg.i]
  spot.at.b = first[0]
  spot.at.c = first[1]
  const pages = []
  for (let k = 0; k < g.cols; k++) {
    const start = pg.starts[pg.i + k] || (k > 0 && pages[k - 1].next) || null
    pages.push(start ? layoutPage(chapter.blocks, start, g) : { lines: [], next: null })
  }
  return { chapter, pg, pages, end: pages[pages.length - 1].next }
}

const hasText = (book, s, p, ui) => chapterOf(book, s, p, ui).blocks.length > 0

// The next part with text after (s, p), or null at the end of the book.
export function nextPart(book, s, p, ui) {
  let at = { s, p }
  for (let guard = 0; guard < 400; guard++) {
    const chapter = chapterOf(book, at.s, at.p, ui)
    at = chapter.more ? { s: at.s, p: at.p + 1 } : { s: at.s + 1, p: 0 }
    if (at.s >= book.spine.length) return null
    if (hasText(book, at.s, at.p, ui)) return at
  }
  return null
}

export function prevPart(book, s, p, ui) {
  let at = { s, p }
  for (let guard = 0; guard < 400; guard++) {
    if (at.p > 0) at = { s: at.s, p: at.p - 1 }
    else {
      if (at.s === 0) return null
      // The chapter before, at its last part.
      let q = 0
      while (q < 50 && chapterOf(book, at.s - 1, q, ui).more) q++
      at = { s: at.s - 1, p: q }
    }
    if (hasText(book, at.s, at.p, ui)) return at
  }
  return null
}

// A spread forward or back. False at either end of the book.
export function turn(spot, book, by, g, ui) {
  const at = spot.at
  let { chapter, pg } = pagesFor(spot, book, at, g, ui)
  if (by > 0) {
    // The pages of the spread after this one, laid out once and kept.
    let ok = true
    for (let k = 0; k < g.cols; k++) {
      const i = pg.i + k
      if (pg.starts.length > i + 1) continue
      const next = layoutPage(chapter.blocks, pg.starts[i], g).next
      if (!next) {
        ok = false
        break
      }
      pg.starts.push(next)
    }
    if (ok && pg.starts.length > pg.i + g.cols) {
      pg.i += g.cols
    } else {
      const part = nextPart(book, at.s, at.p, ui)
      if (!part) return false
      spot.pg = null
      Object.assign(at, part, { b: 0, c: 0 })
      return true
    }
  } else if (pg.i - g.cols >= 0) {
    pg.i -= g.cols
  } else {
    const part = prevPart(book, at.s, at.p, ui)
    if (!part) return false
    Object.assign(at, part)
    spot.pg = null
    pg = pagesFor(spot, book, { s: at.s, p: at.p, b: 1e9, c: 0 }, g, ui).pg
  }
  const start = pg.starts[pg.i]
  at.b = start[0]
  at.c = start[1]
  return true
}

// Opens at a place: the page it is on.
export function jumpTo(spot, place) {
  spot.at = { s: place.s, p: place.p || 0, b: place.b || 0, c: place.c || 0 }
  spot.pg = null
}

// ---- How far through -------------------------------------------------------------

// The characters of a part before [b, c].
export function charsBefore(blocks, b, c) {
  let done = 0
  for (let i = 0; i < b && i < blocks.length; i++) done += blocks[i].t.length + 1
  return done + (c || 0)
}

// How far through the book a place is, from 0 to 1, by the chapters' sizes.
export function shareOf(book, at, chapter, ui) {
  const w = book.w
  let total = 0
  let beforeIt = 0
  for (let i = 0; i < w.length; i++) {
    total += w[i]
    if (i < at.s) beforeIt += w[i]
  }
  const parts = partsOf(book, at.s, ui)
  const inPart = chapter && chapter.chars > 0 ? Math.min(1, charsBefore(chapter.blocks, at.b || 0, at.c || 0) / chapter.chars) : 0
  const inChapter = Math.min(1, ((at.p || 0) + inPart) / parts)
  return total > 0 ? Math.min(1, (beforeIt + inChapter * w[at.s]) / total) : 0
}

// The place at a share of the book: its chapter, part and block.
export function placeAt(book, share, ui) {
  const w = book.w
  const total = w.reduce((a, b) => a + b, 0)
  let target = Math.max(0, Math.min(1, share)) * total
  let s = 0
  while (s < w.length - 1 && target >= w[s]) {
    target -= w[s]
    s++
  }
  const inChapter = Math.max(0, Math.min(0.9999, target / w[s]))
  const parts = partsOf(book, s, ui)
  const p = Math.min(parts - 1, Math.floor(inChapter * parts))
  const chapter = chapterOf(book, s, p, ui)
  const want = (inChapter * parts - p) * chapter.chars
  let b = 0
  let done = 0
  while (b < chapter.blocks.length - 1 && done + chapter.blocks[b].t.length + 1 <= want) {
    done += chapter.blocks[b].t.length + 1
    b++
  }
  return { s, p, b, c: 0 }
}

// The book's text left after a place, in characters: this part's own, and
// the rest by the chapters' sizes at this part's ratio of text to XHTML.
export function charsLeft(book, at, chapter, ui) {
  const here = Math.max(0, chapter.chars - charsBefore(chapter.blocks, at.b || 0, at.c || 0))
  const parts = partsOf(book, at.s, ui)
  const partSize = book.w[at.s] / parts
  const ratio = chapter.chars > 0 && partSize > 0 ? Math.min(1, chapter.chars / partSize) : 0.6
  let rest = 0
  for (let i = at.s + 1; i < book.w.length; i++) rest += book.w[i]
  const restOfChapter = (parts - 1 - (at.p || 0)) * partSize
  return { chapter: here + restOfChapter * ratio, book: here + (restOfChapter + rest) * ratio }
}

