// A book's pages: the spread, its pictures, the highlights on it and the
// passage being picked, the bookmark's ribbon, the bars above and below, and
// the sheets that come up over the page (text and layout, go to a place, the
// end of the book).

import { Z, px, raw, Icon, I, Btn, Meter, duration } from './ui'
import { picturesFor } from './epub'
import { SIZES, xOf, justified, wordAt } from './pages'
import { highlightsIn } from './marks'

// The tools in the reader's top bar.
function Tool({ ui, icon, label, onClick, on, width }) {
  return (
    <div
      look={on ? 'selected' : 'button'}
      className={`flex items-center justify-center h-[${px(30)}] min-w-[${px(34)}] px-[${px(7)}] rounded-[${px(8)}] shrink-0 ${on ? ui.accent : ui.sheetSoft} ${ui.sheetPress}`}
      onClick={onClick}
    >
      {icon ? <Icon d={icon} size={18} stroke width={width || 2} /> : null}
      {label ? <span className={`text-[${px(14)}]`}>{label}</span> : null}
    </div>
  )
}

// A band behind (or under, on paper) characters `from` to `to` of a line.
function band(ui, left, top, line, from, to, justify, kind) {
  const x0 = Math.round(xOf(line, from, justify))
  const x1 = Math.round(xOf(line, to, justify))
  if (x1 - x0 < 1) return null
  if (ui.ink) {
    // Paper has no colour to mark with: a rule under the words, thicker for
    // the passage being picked.
    const h = Math.max(kind === 'sel' ? 4 : 2, Math.round((kind === 'sel' ? 4 : 2) * Z.zoom))
    return <div className={`absolute left-[${raw(left + x0)}] top-[${raw(top + line.lh - h - Math.round(line.lh * 0.08))}] w-[${raw(x1 - x0)}] h-[${raw(h)}] bg-black`} />
  }
  const pad = Math.round(line.lh * 0.08)
  return (
    <div
      className={`absolute left-[${raw(left + x0 - 1)}] top-[${raw(top + pad)}] w-[${raw(x1 - x0 + 2)}] h-[${raw(line.lh - pad * 2)}] rounded-[${px(2)}] bg-[${kind === 'sel' ? ui.selColor : ui.markColor}]`}
    />
  )
}

// The overlap of a line with a range [b, c] .. [b2, c2] of its part.
function overlap(line, r) {
  if (line.b < r.b || line.b > r.b2) return null
  const from = line.b === r.b ? Math.max(line.c, r.c) : line.c
  const to = line.b === r.b2 ? Math.min(line.e, r.c2) : line.e
  return from < to ? [from, to] : null
}

export function Reader({ ui, spot, book, g, prefs, spread, marks, bookmark, share, left, A }) {
  const { chapter, pages } = spread
  const at = spot.at
  // The pictures on the spread, decoded at the size they are drawn.
  const pictureKey = (line) => `${book.path}|${line.img}|${line.w}x${line.h}`
  const wanted = []
  for (const page of pages) for (const line of page.lines) if (line.img) wanted.push({ key: pictureKey(line), path: book.path, src: line.img, w: line.w, h: line.h })
  const shown = picturesFor(wanted, ui.paperColor)
  const end = !spread.end && !chapter.more && at.s >= book.spine.length - 1
  const percent = end ? 100 : Math.floor(share * 100)
  let label = ''
  for (const entry of book.toc || []) if (entry.s <= at.s) label = entry.label
  const justify = prefs.justify
  const selm = spot.selm && spot.selm.s === at.s && (spot.selm.p || 0) === (at.p || 0) ? spot.selm : null
  const ranges = highlightsIn(marks, at.s, at.p || 0)
  const pick = selm ? normal(selm) : null
  const textOf = (b) => (chapter.blocks[b] ? chapter.blocks[b].t : '')

  const under = []
  const over = []
  pages.forEach((page, k) => {
    const colLeft = g.margin + k * (g.w + g.gap)
    for (const line of page.lines) {
      const left = colLeft + line.x
      const top = g.top + line.y
      if (line.img) {
        const ref = shown.get(pictureKey(line))
        over.push(
          ref ? (
            <img className={`absolute left-[${raw(left)}] top-[${raw(top)}] w-[${raw(line.w)}] h-[${raw(line.h)}]`} src={ref} />
          ) : (
            <div
              className={`absolute left-[${raw(left)}] top-[${raw(top)}] w-[${raw(line.w)}] h-[${raw(line.h)}] flex items-center justify-center p-[${px(8)}] border border-[${ui.rule}] text-center text-[${px(14)}] ${ui.sheetMuted}`}
            >
              {line.alt || 'A picture'}
            </div>
          ),
        )
        continue
      }
      if (line.hr) {
        over.push(
          <svg className={`absolute left-[${raw(colLeft)}] top-[${raw(top)}]`} width={g.w} height={line.lh} viewBox={`0 0 ${g.w} ${line.lh}`}>
            <path fill="none" stroke={ui.rule} strokeWidth={Math.max(1, Math.round(Z.zoom))} d={`M${Math.round(g.w * 0.35)} ${Math.round(line.lh / 2)}H${Math.round(g.w * 0.65)}`} />
          </svg>,
        )
        continue
      }
      for (const r of ranges) {
        const o = overlap(line, r)
        if (o) {
          under.push(band(ui, left, top, line, o[0], o[1], justify, 'mark'))
          // A note's sign in the margin beside the highlight's first line.
          if (r.n && line.b === r.b && r.c >= line.c && r.c < Math.max(line.e, line.c + 1)) {
            const size = Math.max(11, Math.min(Math.round(g.margin * 0.6), Math.round(line.fs * 0.6)))
            over.push(
              <div className={`absolute left-[${raw(colLeft - size - Math.max(3, Math.round(g.margin * 0.15)))}] top-[${raw(top + Math.round((line.lh - size) / 2))}] ${ui.sheetMuted}`}>
                <Icon d={I.pen} size={Math.round(size / Z.zoom)} stroke width={2.4} />
              </div>,
            )
          }
        }
      }
      if (pick) {
        const o = overlap(line, pick)
        if (o) under.push(band(ui, left, top, line, o[0], o[1], justify, 'sel'))
      }
      const cls = `absolute left-[${raw(left)}] top-[${raw(top)}] h-[${raw(line.lh)}] leading-[${raw(line.lh)}] text-[${raw(line.fs)}] whitespace-nowrap ${line.bold ? 'font-bold' : ''}`
      if (justify && line.j && line.t.indexOf(' ') > 0) {
        // Justified: each word where justified() puts it, as one row.
        over.push(
          <div className={`${cls} flex justify-between w-[${raw(line.w)}]`}>
            {justified(line).map((word) => (
              <span>{word.t}</span>
            ))}
          </div>,
        )
      } else {
        over.push(<div className={cls}>{line.t}</div>)
      }
    }
  })

  // The ribbon of a bookmarked page.
  const ribbonW = Math.round(16 * Z.zoom)
  const ribbon = bookmark ? (
    <svg className={`absolute right-[${raw(Math.max(4, g.margin / 2 - ribbonW / 2))}] top-[${raw(g.bar)}] w-[${raw(ribbonW)}] h-[${raw(ribbonW * 1.5)}]`} viewBox="0 0 16 24">
      <path d="M0 0H16V24L8 18L0 24Z" fill={ui.ink ? '#000000' : '#c0392b'} />
    </svg>
  ) : null

  // How long is left: this chapter's text and the book's, at your pace.
  const leftText = left ? (left.chapter > 30 ? `${duration(left.chapter)} left in chapter` : 'Chapter ends here') : ''

  const statusH = g.foot
  const width = ui.width
  const ticks = []
  if (prefs.status !== 'none' && book.w.length > 1 && book.w.length <= 80) {
    const total = book.w.reduce((a, b) => a + b, 0)
    let sum = 0
    for (let s = 0; s < book.w.length - 1; s++) {
      sum += book.w[s]
      ticks.push(Math.round((width * sum) / total))
    }
  }
  const progress = Math.round((width * percent) / 100)
  const barH = Math.max(2, Math.round((prefs.status === 'bar' ? 4 : 3) * Z.zoom))
  const selecting = !!spot.selm

  return (
    <div className={`relative w-full h-full ${ui.sheet}`}>
      {under}
      {over}
      {ribbon}
      {end ? <div className={`absolute right-[${raw(g.margin)}] bottom-[${raw(statusH + 2)}] text-[${px(14)}] ${ui.sheetMuted}`}>The end</div> : null}
      <div
        className={`absolute left-0 right-0 top-[${raw(g.bar)}] bottom-[${raw(statusH)}]`}
        onClick={(e) => {
          if (selecting) {
            const word = wordAt(pages, g, e.localX, e.localY + g.bar, justify, textOf)
            if (word) A.pickTo(word)
            return
          }
          A.turn(e.localX < e.width / 3 ? -1 : 1)
        }}
        onLongPress={(e) => {
          const word = wordAt(pages, g, e.localX, e.localY + g.bar, justify, textOf)
          if (word) A.pickFrom(word)
        }}
        onSwipe={(e) => {
          if (e.direction === 'left' || e.direction === 'up') A.turn(1)
          else if (e.direction === 'right' || e.direction === 'down') A.turn(-1)
        }}
      />
      <div className={`absolute left-0 right-0 top-0 flex items-center gap-[${px(6)}] h-[${raw(g.bar)}] px-[${raw(Math.max(4, g.margin - 8 * Z.zoom))}]`}>
        <Tool ui={ui} icon={I.book} onClick={() => A.go({ view: 'library' })} />
        <div className={`flex-1 min-w-0 h-full flex items-center ${ui.sheetMuted}`} onClick={() => A.go({ view: 'contents', tab: 'toc', lists: null })}>
          <span className={`truncate text-[${px(14)}]`}>{[book.title, label && label !== book.title ? label : ''].filter(Boolean).join(' · ')}</span>
        </div>
        <Tool ui={ui} icon={I.type} onClick={() => A.go({ sheet: spot.sheet === 'type' ? null : 'type' })} on={spot.sheet === 'type'} width={1.8} />
        <Tool ui={ui} icon={bookmark ? I.ribbon : I.ribbonLine} onClick={() => A.bookmark()} on={!!bookmark} />
        <Tool ui={ui} icon={I.menu} onClick={() => A.go({ view: 'menu', lists: null })} width={2.2} />
      </div>
      {prefs.status === 'full' ? (
        <div
          className={`absolute left-0 right-0 bottom-0 flex items-center justify-between gap-[${px(10)}] h-[${raw(statusH)}] px-[${raw(g.margin)}] text-[${px(13)}] ${ui.sheetMuted}`}
          onClick={() => A.go({ sheet: 'goto', gotoF: share })}
        >
          <span className="whitespace-nowrap">{`Chapter ${at.s + 1} of ${book.spine.length}`}</span>
          <span className="truncate">{leftText}</span>
          <span className="whitespace-nowrap">{`${percent}%`}</span>
        </div>
      ) : prefs.status === 'bar' ? (
        <div className={`absolute left-0 right-0 bottom-0 h-[${raw(statusH)}]`} onClick={() => A.go({ sheet: 'goto', gotoF: share })} />
      ) : null}
      {prefs.status !== 'none'
        ? [
            ...ticks.map((x) => <div className={`absolute left-[${raw(x)}] bottom-0 w-[${raw(Math.max(1, Math.round(Z.zoom)))}] h-[${raw(barH * 2)}] bg-[${ui.rule}]`} />),
            progress > 0 ? <div className={`absolute left-0 bottom-0 w-[${raw(progress)}] h-[${raw(barH)}] bg-[${ui.ink ? '#000000' : ui.rule}]`} /> : null,
          ]
        : null}
      {selecting ? <PickBar ui={ui} spot={spot} g={g} A={A} /> : null}
      {spot.sheet === 'type' ? <TypeSheet ui={ui} prefs={prefs} g={g} A={A} /> : null}
      {spot.sheet === 'goto' ? <GotoSheet ui={ui} spot={spot} book={book} A={A} /> : null}
      {spot.sheet === 'end' ? <EndSheet ui={ui} spot={spot} book={book} A={A} /> : null}
    </div>
  )
}

// A range with its ends in order.
export function normal(selm) {
  const a = selm.a
  const z = selm.z
  const swap = z[0] < a[0] || (z[0] === a[0] && z[1] < a[1])
  const from = swap ? z : a
  const to = swap ? a : z
  return { b: from[0], c: from[1], b2: to[0], c2: Math.max(to[1], from[0] === to[0] ? from[1] + 1 : 0) }
}

// The bar under the page while a passage is picked.
function PickBar({ ui, spot, g, A }) {
  const selm = spot.selm
  const hint = selm.phase === 'start' ? (selm.keys ? 'Next and Prev move the start; Action picks it' : 'Tap where it starts, or where it ends') : selm.keys ? 'Next and Prev move the end; Action highlights' : 'Tap the last word; swipe for the next page'
  return (
    <div className={`absolute left-0 right-0 bottom-0 flex items-center gap-[${px(6)}] px-[${px(10)}] py-[${px(6)}] ${ui.sheetSoft} ${ui.ink ? '' : 'border-t'} border-[${ui.rule}]`}>
      <span className={`flex-1 min-w-0 text-[${px(13)}] ${ui.sheetMuted} truncate`}>{hint}</span>
      <Btn ui={ui} sheet small size={34} label="Cancel" onClick={() => A.go({ selm: null })} />
      <Btn ui={ui} sheet small size={34} label="Note" icon={I.pen} onClick={() => A.keepPick(true)} />
      <Btn ui={ui} sheet small size={34} primary label="Highlight" onClick={() => A.keepPick(false)} />
    </div>
  )
}

// One row of the text and layout sheet: its name and its choices.
function Choice({ ui, name, options, value, set }) {
  return (
    <div className={`flex items-center gap-[${px(6)}] min-h-[${px(40)}]`}>
      <span className={`w-[${px(96)}] shrink-0 text-[${px(14)}] ${ui.sheetMuted}`}>{name}</span>
      <div className={`flex items-center gap-[${px(4)}] flex-1 min-w-0`}>
        {options.map(([label, v]) => (
          <Btn ui={ui} sheet grow small size={34} label={label} on={v === value} onClick={() => set(v)} />
        ))}
      </div>
    </div>
  )
}

function TypeSheet({ ui, prefs, g, A }) {
  const set = (key) => (value) => A.prefs({ [key]: value })
  const wide = ui.width / Z.zoom > 600
  const rows = [
    <div className={`flex items-center gap-[${px(6)}] min-h-[${px(40)}]`}>
      <span className={`w-[${px(96)}] shrink-0 text-[${px(14)}] ${ui.sheetMuted}`}>Text size</span>
      <Btn ui={ui} sheet small size={34} label="A−" onClick={() => A.prefs({ size: Math.max(0, prefs.size - 1) })} />
      <span className={`flex-1 text-center text-[${px(14)}]`}>{`${SIZES[prefs.size]} px`}</span>
      <Btn ui={ui} sheet small size={34} label="A+" onClick={() => A.prefs({ size: Math.min(SIZES.length - 1, prefs.size + 1) })} />
    </div>,
    <Choice ui={ui} name="Spacing" value={prefs.spacing} set={set('spacing')} options={[['Tight', 0], ['Normal', 1], ['Loose', 2]]} />,
    <Choice ui={ui} name="Margins" value={prefs.margin} set={set('margin')} options={[['Narrow', 0], ['Normal', 1], ['Wide', 2]]} />,
    <Choice ui={ui} name="Alignment" value={prefs.justify} set={set('justify')} options={[['Left', false], ['Justified', true]]} />,
    ui.ink ? null : <Choice ui={ui} name="Page" value={prefs.theme} set={set('theme')} options={[['Light', 'light'], ['Sepia', 'sepia'], ['Dark', 'dark']]} />,
    <Choice ui={ui} name="Status bar" value={prefs.status} set={set('status')} options={[['Full', 'full'], ['Line', 'bar'], ['None', 'none']]} />,
    wide ? <Choice ui={ui} name="Columns" value={prefs.columns} set={set('columns')} options={[['Auto', 0], ['One', 1]]} /> : null,
  ].filter(Boolean)
  return (
    <div className={`absolute left-0 right-0 bottom-0 flex flex-col max-h-[${raw(ui.height - g.bar)}] ${ui.sheet} ${ui.ink ? 'border-t-2 border-black' : 'border-t'} border-[${ui.rule}]`}>
      <div className={`flex items-center h-[${px(40)}] px-[${px(14)}] shrink-0`}>
        <span className={`flex-1 text-[${px(16)}] font-bold`}>Text and layout</span>
        <Btn ui={ui} sheet small size={32} label="Done" primary onClick={() => A.go({ sheet: null })} />
      </div>
      <div className={`${wide ? 'grid grid-cols-2 gap-x-[' + px(18) + ']' : 'flex flex-col'} overflow-y-auto px-[${px(14)}] pb-[${px(10)}] gap-y-[${px(2)}]`}>{rows}</div>
    </div>
  )
}

// Go to a place: the book as a line with its chapters on it.
function GotoSheet({ ui, spot, book, A }) {
  const f = Math.max(0, Math.min(1, typeof spot.gotoF === 'number' ? spot.gotoF : 0))
  const place = A.placeAt(f)
  let label = `Chapter ${place.s + 1}`
  for (const entry of book.toc || []) if (entry.s <= place.s) label = entry.label
  const w = ui.width - Math.round(48 * Z.zoom)
  const set = (e) => A.go({ gotoF: Math.max(0, Math.min(1, e.localX / e.width)) })
  const step = (by) => A.go({ gotoF: Math.max(0, Math.min(1, f + by)) })
  const chapter = (by) => {
    const total = book.w.reduce((a, b) => a + b, 0)
    const s = Math.max(0, Math.min(book.w.length - 1, place.s + by))
    let sum = 0
    for (let i = 0; i < s; i++) sum += book.w[i]
    A.go({ gotoF: Math.min(1, (sum + 1) / total) })
  }
  return (
    <div className={`absolute left-0 right-0 bottom-0 flex flex-col gap-[${px(10)}] px-[${px(24)}] py-[${px(14)}] ${ui.sheet} ${ui.ink ? 'border-t-2 border-black' : 'border-t'} border-[${ui.rule}]`}>
      <div className="flex items-center">
        <span className={`flex-1 min-w-0 truncate text-[${px(16)}] font-bold`}>{label}</span>
        <span className={`text-[${px(16)}] ${ui.sheetMuted}`}>{`${Math.round(f * 100)}%`}</span>
      </div>
      <div
        className={`relative h-[${px(28)}] flex items-center`}
        onPointerDown={ui.fast ? set : undefined}
        onPointerMove={ui.fast ? (e) => (e.buttons ? set(e) : false) : undefined}
        onClick={set}
      >
        <Meter ui={ui} share={f} w={w} h={8 * Z.zoom} onSheet />
      </div>
      <div className={`flex items-center gap-[${px(6)}]`}>
        <Btn ui={ui} sheet small size={36} label="−10%" onClick={() => step(-0.1)} />
        <Btn ui={ui} sheet small size={36} icon={I.left} onClick={() => chapter(-1)} />
        <Btn ui={ui} sheet small size={36} icon={I.right} onClick={() => chapter(1)} />
        <Btn ui={ui} sheet small size={36} label="+10%" onClick={() => step(0.1)} />
        <div className="flex-1" />
        <Btn ui={ui} sheet small size={36} label="Cancel" onClick={() => A.go({ sheet: null })} />
        <Btn ui={ui} sheet small size={36} label="Go" primary onClick={() => A.goTo(f)} />
      </div>
    </div>
  )
}

function EndSheet({ ui, spot, book, A }) {
  const place = (spot.books && spot.books[book.path]) || {}
  const days = place.first ? Math.max(1, Math.round((Date.now() - place.first) / 86400000)) : 0
  return (
    <div className={`absolute left-0 right-0 bottom-0 flex flex-col items-center gap-[${px(8)}] px-[${px(24)}] py-[${px(18)}] ${ui.sheet} ${ui.ink ? 'border-t-2 border-black' : 'border-t'} border-[${ui.rule}]`}>
      <Icon d={I.flag} size={28} stroke width={2} />
      <span className={`text-[${px(20)}] font-bold text-center`}>{`You finished ${book.title}`}</span>
      <span className={`text-[${px(14)}] ${ui.sheetMuted} text-center`}>
        {place.secs ? `${duration(place.secs)} of reading${days > 1 ? ` over ${days} days` : ''}, ${place.pages || 0} pages turned.` : 'The end of the book.'}
      </span>
      <div className={`flex items-center gap-[${px(8)}] pt-[${px(6)}]`}>
        <Btn ui={ui} sheet small size={38} label="Stay here" onClick={() => A.go({ sheet: null })} />
        <Btn ui={ui} sheet small size={38} label="Notes" onClick={() => A.go({ sheet: null, view: 'contents', tab: 'marks', lists: null })} />
        <Btn ui={ui} sheet small size={38} primary label="Library" onClick={() => A.go({ sheet: null, view: 'library' })} />
      </div>
    </div>
  )
}

