// The pages around the book: the library, the book's menu, its contents and
// marks, a mark, a note being written, a search in the book, the reading
// stats, and the catalogs of free books.

import { Z, px, raw, Icon, I, Btn, Meter, Listing, Title, Page, duration, ago, sizeText } from './ui'
import { cut, kindName } from './marks'

// ---- The library ---------------------------------------------------------------------

export function LibraryView({ ui, list, A, spot, count, where, notice }) {
  const wide = ui.width / Z.zoom >= 480
  const filter = spot.filter || 'all'
  const tab = (id, label) => <Btn ui={ui} small size={32} label={label} on={filter === id} onClick={() => A.go({ filter: id, sel: 0, page: 0 })} />
  const sortLabel = { recent: 'Recent', title: 'Title', author: 'Author' }[spot.sort || 'recent']
  return (
    <Listing
      ui={ui}
      title={<Title ui={ui} title="Books" sub={notice || (count > 0 ? `${count} book${count === 1 ? '' : 's'}` : '')} />}
      actions={[
        <Btn ui={ui} icon={I.download} onClick={() => A.go({ view: 'catalog', lists: null })} />,
        <Btn ui={ui} icon={I.chart} onClick={() => A.go({ view: 'stats' })} />,
        count === 0 ? null : <Btn ui={ui} icon={I.refresh} onClick={() => A.go({ refresh: true, problem: '' })} />,
      ]}
      tabs={
        count === 0
          ? null
          : [
              tab('all', 'All'),
              tab('reading', 'Reading'),
              tab('done', 'Finished'),
              <div className="flex-1" />,
              wide ? <span className={`text-[${px(13)}] ${ui.muted}`}>Sort</span> : null,
              <Btn ui={ui} small size={32} label={sortLabel} onClick={() => A.go({ sort: { recent: 'title', title: 'author', author: 'recent' }[spot.sort || 'recent'], sel: 0, page: 0 })} />,
            ]
      }
      pages={list.pages}
      page={list.page}
      sel={list.sel}
      keys={spot.keys === true}
      onPage={(by) => A.go({ page: list.page + by })}
      onOpen={(i) => A.open(i)}
      empty={
        count === 0
          ? `${spot.looked ? 'Looked again: still no books.' : 'No books yet.'} Get free books here, or put .epub files on ${where}.`
          : filter === 'done'
            ? 'No finished books yet.'
            : 'Nothing being read: open a book from All.'
      }
      emptyAction={
        count === 0 ? (
          <div className={`flex items-center gap-[${px(8)}] mt-[${px(8)}]`}>
            <Btn ui={ui} primary icon={I.download} label="Get free books" onClick={() => A.go({ view: 'catalog', lists: null })} />
            <Btn ui={ui} icon={I.refresh} label="Look again" onClick={() => A.go({ refresh: true, problem: '' })} />
          </div>
        ) : null
      }
    />
  )
}

// ---- A list with a back arrow ---------------------------------------------------------

export function ListPage({ ui, spot, title, sub, list, A, onBack, onOpen, empty, actions, tabs, footer }) {
  return (
    <Listing
      ui={ui}
      title={<Title ui={ui} title={title} sub={sub} onBack={onBack} />}
      actions={actions}
      tabs={tabs}
      footer={footer}
      pages={list.pages}
      page={list.page}
      sel={list.sel}
      keys={spot.keys === true}
      onPage={(by) => A.page(by)}
      onOpen={onOpen}
      empty={empty}
    />
  )
}

// ---- A mark --------------------------------------------------------------------------

export function MarkView({ ui, spot, mark, A, book, now }) {
  const sure = spot.sure === mark.id
  return (
    <Page
      ui={ui}
      title={kindName(mark)}
      sub={`${mark.ch || `Chapter ${mark.s + 1}`} · ${Math.round((mark.f || 0) * 100)}% · ${ago(mark.at, now)}`}
      onBack={() => A.go({ view: 'contents', tab: 'marks' })}
      footer={[
        <Btn ui={ui} primary label="Go to it" icon={I.book} onClick={() => A.goMark(mark)} />,
        mark.k === 'h' ? <Btn ui={ui} label={mark.n ? 'Edit note' : 'Add note'} icon={I.pen} onClick={() => A.editNote(mark)} /> : null,
        <div className="flex-1" />,
        <Btn ui={ui} label={sure ? 'Delete it' : 'Delete'} icon={I.trash} on={sure} onClick={() => (sure ? A.dropMark(mark) : A.go({ sure: mark.id }))} />,
      ]}
    >
      <div className={`flex gap-[${px(10)}] p-[${px(14)}] rounded-[${px(10)}] ${ui.card}`}>
        <div className={`w-[${px(4)}] shrink-0 rounded-full bg-[${ui.ink ? '#000000' : mark.k === 'b' ? '#c0392b' : '#e2b93b'}]`} />
        <span className={`text-[${px(17)}] leading-[${px(25)}]`}>{mark.t ? (mark.k === 'b' ? cut(mark.t, 400) : cut(mark.t, 900)) : 'The page this bookmark keeps.'}</span>
      </div>
      {mark.n ? (
        <div className={`flex flex-col gap-[${px(4)}] p-[${px(14)}] rounded-[${px(10)}] ${ui.card}`}>
          <span className={`text-[${px(13)}] font-bold ${ui.muted}`}>Your note</span>
          <span className={`text-[${px(16)}] leading-[${px(23)}]`}>{mark.n}</span>
        </div>
      ) : null}
      <span className={`text-[${px(13)}] ${ui.muted}`}>{book ? `${book.title}${book.author ? ` · ${book.author}` : ''}` : ''}</span>
    </Page>
  )
}

// ---- A note being written ---------------------------------------------------------------

export function NoteView({ ui, mark, text, A }) {
  return (
    <Page
      ui={ui}
      title={mark.n ? 'Edit note' : 'Add a note'}
      sub={cut(mark.t, 80)}
      onBack={() => A.go({ view: 'mark' })}
      footer={[
        <div className="flex-1" />,
        <Btn ui={ui} label="Cancel" onClick={() => A.go({ view: 'mark' })} />,
        <Btn ui={ui} primary label="Save" icon={I.check} onClick={() => A.saveNote(mark)} />,
      ]}
    >
      <textarea
        className={`w-full h-[${px(150)}] min-h-[${px(90)}] flex-1 p-[${px(10)}] rounded-[${px(8)}] text-[${px(17)}] leading-[${px(24)}] ${ui.card} focus:border-2 focus:border-[${ui.accentColor}]`}
        value={text}
        placeholder="What you thought of it"
        onChange={(e) => A.draft(e.target.value)}
      />
    </Page>
  )
}

// ---- A field and a button: search, a link ------------------------------------------------

export function AskView({ ui, title, sub, value, placeholder, label, A, onBack, onGo, hint, type, children }) {
  return (
    <Page ui={ui} title={title} sub={sub} onBack={onBack}>
      <div className={`flex items-center gap-[${px(8)}]`}>
        <input
          type={type || 'text'}
          className={`flex-1 min-w-0 h-[${px(44)}] px-[${px(12)}] rounded-[${px(10)}] text-[${px(17)}] ${ui.card} focus:border-2 focus:border-[${ui.accentColor}]`}
          value={value}
          placeholder={placeholder}
          onChange={(e) => A.draft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') onGo()
          }}
        />
        <Btn ui={ui} primary label={label} onClick={onGo} />
      </div>
      {hint ? <span className={`text-[${px(13)}] ${ui.muted}`}>{hint}</span> : null}
      {children || null}
    </Page>
  )
}

// ---- Reading stats ----------------------------------------------------------------------

function Figure({ ui, value, label }) {
  return (
    <div className={`flex flex-col gap-[${px(2)}] p-[${px(10)}] rounded-[${px(10)}] ${ui.card}`}>
      <span className={`text-[${px(20)}] font-bold whitespace-nowrap`}>{value}</span>
      <span className={`text-[${px(12)}] ${ui.muted} whitespace-nowrap`}>{label}</span>
    </div>
  )
}

export function StatsView({ ui, s, top, A, notice }) {
  const cols = ui.width / Z.zoom >= 560 ? 4 : 2
  const most = Math.max(60, ...s.week.map((d) => d.secs))
  const chartH = 70
  return (
    <Page
      ui={ui}
      title="Reading"
      sub={notice || (s.streak > 1 ? `${s.streak} days in a row` : 'Your reading, counted page by page')}
      onBack={() => A.go({ view: 'library' })}
      footer={[
        <Btn ui={ui} label="Export notes" icon={I.share} onClick={() => A.exportAll()} />,
        <Btn ui={ui} label="Import" icon={I.inbox} onClick={() => A.importAll()} />,
      ]}
    >
      <div className={`grid grid-cols-${cols} gap-[${px(8)}]`}>
        <Figure ui={ui} value={duration(s.today)} label="Today" />
        <Figure ui={ui} value={duration(s.weekSecs)} label="Last 7 days" />
        <Figure ui={ui} value={`${s.streak} day${s.streak === 1 ? '' : 's'}`} label="Streak" />
        <Figure ui={ui} value={duration(s.total)} label="In all" />
        <Figure ui={ui} value={String(s.pages)} label="Pages turned" />
        <Figure ui={ui} value={String(s.finished)} label="Books finished" />
        <Figure ui={ui} value={String(s.reading)} label="Being read" />
        <Figure ui={ui} value={`${s.wpm} wpm`} label={s.measured ? 'Your pace' : 'Pace (until measured)'} />
      </div>
      <div className={`flex flex-col gap-[${px(6)}] p-[${px(12)}] rounded-[${px(10)}] ${ui.card}`}>
        <span className={`text-[${px(13)}] font-bold ${ui.muted}`}>The last 7 days</span>
        <div className={`flex items-end gap-[${px(8)}] h-[${px(chartH + 18)}]`}>
          {s.week.map((d) => {
            const h = Math.max(d.secs > 0 ? 3 : 1, Math.round((chartH * d.secs) / most))
            return (
              <div className={`flex flex-col items-center justify-end flex-1 h-full gap-[${px(3)}]`}>
                <div className={`w-full h-[${px(h)}] rounded-[${px(3)}] ${d.secs > 0 ? (ui.ink ? 'bg-black' : 'bg-[#3b82f6]') : ui.ink ? 'bg-black' : 'bg-[#232a3a]'}`} />
                <span className={`text-[${px(11)}] ${ui.muted}`}>{d.label}</span>
              </div>
            )
          })}
        </div>
      </div>
      {top.length > 0 ? (
        <div className={`flex flex-col p-[${px(12)}] gap-[${px(6)}] rounded-[${px(10)}] ${ui.card}`}>
          <span className={`text-[${px(13)}] font-bold ${ui.muted}`}>Books</span>
          {top.map((b) => (
            <div className={`flex items-center gap-[${px(10)}]`}>
              <span className={`flex-1 min-w-0 truncate text-[${px(15)}]`}>{b.title}</span>
              <span className={`text-[${px(13)}] ${ui.muted} whitespace-nowrap`}>{`${duration(b.secs)} · ${b.done ? 'finished' : `${Math.round((b.f || 0) * 100)}%`}`}</span>
            </div>
          ))}
        </div>
      ) : null}
    </Page>
  )
}

export const thousands = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ',')

// ---- A catalog's book ----------------------------------------------------------------------

export function EntryView({ ui, entry, A, dl, exists, path, writable, noCard, onBack }) {
  const coverW = Math.round((ui.width / Z.zoom >= 480 ? 120 : 84) * Z.zoom)
  const coverH = Math.round(coverW * 1.5)
  const busy = dl && dl.path === path && dl.state === 'busy'
  const failed = dl && dl.path === path && dl.state === 'failed'
  const facts = [entry.language ? entry.language.toUpperCase() : '', entry.downloads ? `${thousands(entry.downloads)} downloads` : '', entry.size ? sizeText(entry.size) : '']
    .filter(Boolean)
    .join(' · ')
  return (
    <Page
      ui={ui}
      title={entry.source || 'A book'}
      sub="Free to download"
      onBack={onBack}
      footer={
        busy
          ? [
              <div className={`flex flex-col flex-1 min-w-0 gap-[${px(4)}]`}>
                <span className={`text-[${px(14)}]`}>{`Downloading… ${dl.total ? `${sizeText(dl.offset)} of ${sizeText(dl.total)}` : sizeText(dl.offset)}`}</span>
                <Meter ui={ui} share={dl.total ? dl.offset / dl.total : 0.05} w={ui.width - Math.round(140 * Z.zoom)} />
              </div>,
              <Btn ui={ui} label="Stop" onClick={() => A.stopDownload()} />,
            ]
          : exists
            ? [
                <span className={`flex-1 min-w-0 truncate text-[${px(13)}] ${ui.muted}`}>{`In ${path.replace(/\/[^/]*$/, '')}`}</span>,
                <Btn ui={ui} primary label="Read it" icon={I.book} onClick={() => A.openPath(path)} />,
              ]
            : !writable
              ? [<span className={`flex-1 min-w-0 text-[${px(13)}]`}>{noCard}</span>]
              : [
                  <span className={`flex-1 min-w-0 text-[${px(13)}] ${failed ? '' : ui.muted}`}>{failed ? dl.error : `Into ${path.replace(/\/[^/]*$/, '')}`}</span>,
                  <Btn ui={ui} primary label={failed ? 'Try again' : 'Download'} icon={I.download} onClick={() => A.download(entry, path)} />,
                ]
      }
    >
      <div className={`flex gap-[${px(14)}]`}>
        {entry.cover ? (
          <img className={`w-[${raw(coverW)}] h-[${raw(coverH)}] shrink-0 object-cover rounded-[${px(4)}] ${ui.soft}`} src={entry.cover} />
        ) : (
          <div className={`flex items-center justify-center w-[${raw(coverW)}] h-[${raw(coverH)}] shrink-0 rounded-[${px(4)}] ${ui.soft} ${ui.muted}`}>
            <Icon d={I.book} size={36} stroke width={1.6} />
          </div>
        )}
        <div className={`flex flex-col gap-[${px(6)}] flex-1 min-w-0`}>
          <span className={`text-[${px(20)}] font-bold line-clamp-3`}>{entry.title}</span>
          {entry.author ? <span className={`text-[${px(15)}]`}>{entry.author}</span> : null}
          {facts ? <span className={`text-[${px(12)}] ${ui.muted}`}>{facts}</span> : null}
          {entry.subjects && entry.subjects.length ? <span className={`text-[${px(12)}] ${ui.muted} line-clamp-2`}>{entry.subjects.join(' · ')}</span> : null}
        </div>
      </div>
      {entry.summary ? <span className={`text-[${px(15)}] leading-[${px(22)}]`}>{cut(entry.summary, 900)}</span> : null}
    </Page>
  )
}

sources.marks.ts:
// Bookmarks, highlights and notes, per book, in the private disk field
// `marks`: { [book key]: { title, author, list: [mark] } }.
//
// A mark is where it is in the book: its chapter (s), the chapter's part (p),
// the block and character it starts at (b, c), and for a highlight where it
// ends (b2, c2, in the same part). It keeps its text (t), so a list and an
// export say what it is without opening the book, its note (n), when it was
// made (at), how far through the book it is (f) and the chapter's name (ch).
// k is 'b' for a bookmark, 'h' for a highlight (a note is a highlight's).
//
// Exports go to the assets folder as files people already know: Markdown, a
// Kindle "My Clippings.txt" (which Readwise, Calibre and most note tools
// import), and a JSON backup that Import reads back (here or on another frame).

import { MONTHS } from './ui'

export const MAX_TEXT = 1200
export const BACKUP_NAME = 'FrameOS books backup.json'
export const CLIPPINGS_NAME = 'My Clippings.txt'

export function readMarks(app) {
  let marks = app.state.marks
  if (typeof marks === 'string') {
    try {
      marks = JSON.parse(marks)
    } catch (e) {
      marks = null
    }
  }
  return marks && typeof marks === 'object' && !Array.isArray(marks) ? marks : {}
}

export const saveMarks = (marks) => frameos.setState('marks', marks)

export function listOf(marks, key) {
  const entry = marks[key]
  return entry && Array.isArray(entry.list) ? entry.list : []
}

const cmp = (a, b) => a.s - b.s || (a.p || 0) - (b.p || 0) || a.b - b.b || a.c - b.c

export function sorted(list) {
  return list.slice().sort(cmp)
}

let counter = 0
export const newId = (now) => `${Math.floor(now).toString(36)}${(counter++ % 1296).toString(36)}`

// Adds or replaces (by id) a mark of a book.
export function putMark(marks, book, mark) {
  const entry = marks[book.path] && typeof marks[book.path] === 'object' ? marks[book.path] : { list: [] }
  entry.title = book.title
  entry.author = book.author || ''
  const list = Array.isArray(entry.list) ? entry.list.filter((m) => m.id !== mark.id) : []
  list.push(mark)
  entry.list = sorted(list)
  marks[book.path] = entry
  return marks
}

export function dropMark(marks, key, id) {
  const entry = marks[key]
  if (!entry || !Array.isArray(entry.list)) return marks
  entry.list = entry.list.filter((m) => m.id !== id)
  if (entry.list.length === 0) delete marks[key]
  return marks
}

export const findMark = (marks, key, id) => listOf(marks, key).find((m) => m.id === id) || null

// The bookmark on a spread: one in the same part from its start up to where
// the next spread starts (null at the part's end).
export function bookmarkOn(list, at, end) {
  const from = [at.b || 0, at.c || 0]
  return (
    list.find(
      (m) =>
        m.k === 'b' &&
        m.s === at.s &&
        (m.p || 0) === (at.p || 0) &&
        !(m.b < from[0] || (m.b === from[0] && m.c < from[1])) &&
        (!end || m.b < end[0] || (m.b === end[0] && m.c < end[1])),
    ) || null
  )
}

// The highlights in a part.
export const highlightsIn = (list, s, p) => list.filter((m) => m.k === 'h' && m.s === s && (m.p || 0) === p)

// The text between two places of a part's blocks, paragraphs on lines of their own.
export function textBetween(blocks, b, c, b2, c2) {
  const out = []
  for (let i = b; i <= b2 && i < blocks.length; i++) {
    const t = blocks[i].t || ''
    if (!t) continue
    out.push(t.slice(i === b ? c : 0, i === b2 ? c2 : t.length).trim())
  }
  return out.filter(Boolean).join('\n')
}

// ---- Words for a list --------------------------------------------------------------

export const kindName = (m) => (m.k === 'b' ? 'Bookmark' : m.n ? 'Note' : 'Highlight')

export function cut(text, n) {
  const t = String(text || '').replace(/\s+/g, ' ').trim()
  return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t
}

// ---- Exports ---------------------------------------------------------------------------

const pad = (n) => String(n).padStart(2, '0')
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
const LONG_MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']

export function isoDate(ms) {
  const d = new Date(ms)
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

function kindleDate(ms) {
  const d = new Date(ms)
  const h = d.getHours()
  return `${DAYS[d.getDay()]}, ${LONG_MONTHS[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()} ${h % 12 || 12}:${pad(d.getMinutes())}:${pad(d.getSeconds())} ${h < 12 ? 'AM' : 'PM'}`
}

const percent = (f) => `${Math.round((f || 0) * 100)}%`

// One book's marks as Markdown, in the book's order, under its chapters.
export function toMarkdown(entry, now) {
  const list = sorted(entry.list || [])
  const lines = [`# ${entry.title || 'Untitled'}`]
  if (entry.author) lines.push('', `*${entry.author}*`)
  const highlights = list.filter((m) => m.k === 'h').length
  const bookmarks = list.filter((m) => m.k === 'b').length
  lines.push('', `${highlights} highlight${highlights === 1 ? '' : 's'}, ${bookmarks} bookmark${bookmarks === 1 ? '' : 's'}. Exported from a FrameOS frame on ${isoDate(now)}.`)
  let chapter = null
  for (const m of list) {
    const ch = m.ch || `Chapter ${m.s + 1}`
    if (ch !== chapter) {
      lines.push('', `## ${ch}`)
      chapter = ch
    }
    lines.push('')
    if (m.k === 'b') {
      lines.push(`- Bookmark at ${percent(m.f)}${m.t ? `: “${cut(m.t, 120)}”` : ''} (${isoDate(m.at)})`)
    } else {
      for (const para of String(m.t || '').split('\n')) lines.push(`> ${para}`)
      if (m.n) lines.push('', `**Note:** ${m.n}`)
      lines.push('', `<sub>${percent(m.f)} · ${isoDate(m.at)}</sub>`)
    }
  }
  return lines.join('\n') + '\n'
}

// Every book's marks as a Kindle "My Clippings.txt", oldest first, as a
// Kindle writes it: the title (author), what it is and where, a blank line,
// the text, ten equals signs. A highlight with a note is a highlight and a note.
export function toClippings(marks) {
  const all = []
  for (const key of Object.keys(marks)) {
    const entry = marks[key]
    for (const m of entry.list || []) all.push({ entry, m })
  }
  all.sort((a, b) => (a.m.at || 0) - (b.m.at || 0))
  const out = []
  for (const { entry, m } of all) {
    const head = `${entry.title || 'Untitled'}${entry.author ? ` (${entry.author})` : ''}`
    const location = Math.max(1, Math.round((m.f || 0) * 10000))
    const when = `Added on ${kindleDate(m.at || 0)}`
    if (m.k === 'b') {
      out.push(`${head}\n- Your Bookmark at location ${location} | ${when}\n\n\n==========`)
      continue
    }
    out.push(`${head}\n- Your Highlight at location ${location} | ${when}\n\n${String(m.t || '').replace(/\n/g, ' ')}\n==========`)
    if (m.n) out.push(`${head}\n- Your Note at location ${location} | ${when}\n\n${m.n}\n==========`)
  }
  return out.length ? out.join('\n') + '\n' : ''
}

// A file name the assets folder takes, from a book's title.
export function fileName(title) {
  const name = String(title || 'Untitled')
    .replace(/[\/\\:*?"<>|]/g, ' ')
    .replace(/[^\p{L}\p{N} ._()+,;=@'&!-]/gu, '')
    .replace(/\s+/g, ' ')
    .replace(/^[\s.]+/, '')
    .trim()
    .slice(0, 80)
  return name || 'Untitled'
}

// The backup: every mark and where every book was left.
export function toBackup(marks, spot, now) {
  return JSON.stringify(
    {
      format: 'frameos-books',
      version: 1,
      exported: new Date(now).toISOString(),
      marks,
      books: spot.books || {},
      days: spot.days || {},
      totals: spot.totals || {},
    },
    null,
    1,
  )
}

// A backup read back in, merged: marks by id (the newer wins), and each
// book's place where the backup's was read more lately. Returns what changed.
export function mergeBackup(text, marks, spot) {
  let data = null
  try {
    data = JSON.parse(text)
  } catch (e) {
    return { error: 'The backup is not JSON.' }
  }
  if (!data || data.format !== 'frameos-books' || typeof data.marks !== 'object') return { error: 'That is not a FrameOS books backup.' }
  let added = 0
  let places = 0
  for (const key of Object.keys(data.marks || {})) {
    const theirs = data.marks[key]
    if (!theirs || !Array.isArray(theirs.list)) continue
    const mine = marks[key] && Array.isArray(marks[key].list) ? marks[key] : { title: theirs.title, author: theirs.author, list: [] }
    for (const m of theirs.list) {
      if (!m || typeof m !== 'object' || typeof m.s !== 'number' || !m.id) continue
      const there = mine.list.findIndex((x) => x.id === m.id)
      if (there < 0) {
        mine.list.push(m)
        added++
      } else if ((m.at || 0) > (mine.list[there].at || 0)) {
        mine.list[there] = m
        added++
      }
    }
    mine.list = sorted(mine.list)
    marks[key] = mine
  }
  const books = spot.books && typeof spot.books === 'object' ? spot.books : {}
  for (const key of Object.keys(data.books || {})) {
    const theirs = data.books[key]
    if (!theirs || typeof theirs.s !== 'number') continue
    if (!books[key] || (theirs.t || 0) > (books[key].t || 0)) {
      books[key] = theirs
      places++
    }
  }
  spot.books = books
  const days = spot.days && typeof spot.days === 'object' ? spot.days : {}
  for (const day of Object.keys(data.days || {})) days[day] = Math.max(days[day] || 0, Number(data.days[day]) || 0)
  spot.days = days
  return { added, places }
}

export function shortDate(ms) {
  const d = new Date(ms)
  return `${d.getDate()} ${MONTHS[d.getMonth()]}`
}

sources.stats.ts:
// Reading, counted: the time between page turns (a page left open longer
// than PAGE_MAX counts as PAGE_MAX, one shorter than a second as a flip), per
// book and per day, the pages turned, and how fast you read, in characters a
// second, which is what "time left" is worked out from.

import { isoDate } from './marks'

export const PAGE_MAX = 4 * 60
const DAYS_KEPT = 120
const DEFAULT_SPEED = 17 // characters a second: about 200 words a minute

export function readingSpeed(spot) {
  const v = Number(spot.speed)
  return v > 2 && v < 200 ? v : DEFAULT_SPEED
}

// A page turn (or leaving the book) at `now`, after `chars` characters read
// forward since the last one.
export function countTurn(spot, key, chars, now, forward) {
  const last = spot.last && typeof spot.last === 'object' ? spot.last : null
  spot.last = { key, t: now }
  if (!last || last.key !== key) return 0
  const dt = (now - last.t) / 1000
  if (!(dt >= 1)) return 0
  const secs = Math.min(dt, PAGE_MAX)
  const books = spot.books && typeof spot.books === 'object' ? spot.books : (spot.books = {})
  const place = books[key] || (books[key] = {})
  place.secs = (place.secs || 0) + secs
  if (forward) place.pages = (place.pages || 0) + 1
  if (!place.first) place.first = now
  const days = spot.days && typeof spot.days === 'object' ? spot.days : (spot.days = {})
  const day = isoDate(now)
  days[day] = (days[day] || 0) + secs
  const totals = spot.totals && typeof spot.totals === 'object' ? spot.totals : (spot.totals = {})
  totals.secs = (totals.secs || 0) + secs
  if (forward) totals.pages = (totals.pages || 0) + 1
  // Only a page read at a reading pace says how fast: not a flip, not one
  // left open over lunch.
  if (forward && chars > 200 && dt > 4 && dt < PAGE_MAX) {
    const pace = chars / dt
    spot.speed = Math.round((spot.speed > 0 ? spot.speed * 0.85 + pace * 0.15 : pace) * 100) / 100
  }
  const keys = Object.keys(days).sort()
  for (const old of keys.slice(0, Math.max(0, keys.length - DAYS_KEPT))) delete days[old]
  return secs
}

// Days in a row with reading, up to today (or yesterday, when today has none yet).
export function streak(days, now) {
  let n = 0
  let t = now
  if (!(days[isoDate(t)] > 0)) t -= 86400000
  while (days[isoDate(t)] > 0) {
    n++
    t -= 86400000
  }
  return n
}

// The last `n` days, oldest first: { day, secs, label }.
export function lastDays(days, now, n) {
  const out = []
  for (let i = n - 1; i >= 0; i--) {
    const t = now - i * 86400000
    const d = new Date(t)
    out.push({ day: isoDate(t), secs: days[isoDate(t)] || 0, label: 'SMTWTFS'[d.getDay()] })
  }
  return out
}

export function summary(spot, now) {
  const days = spot.days && typeof spot.days === 'object' ? spot.days : {}
  const books = spot.books && typeof spot.books === 'object' ? spot.books : {}
  const week = lastDays(days, now, 7)
  const keys = Object.keys(books)
  return {
    today: days[isoDate(now)] || 0,
    week,
    weekSecs: week.reduce((a, d) => a + d.secs, 0),
    streak: streak(days, now),
    total: (spot.totals && spot.totals.secs) || 0,
    pages: (spot.totals && spot.totals.pages) || 0,
    finished: keys.filter((k) => books[k].done).length,
    reading: keys.filter((k) => !books[k].done && books[k].f > 0).length,
    wpm: Math.round((readingSpeed(spot) * 60) / 5.7),
    measured: Number(spot.speed) > 0,
  }
}

sources.catalog.ts:
// Free books, found and downloaded on the frame.
//
// Sources: Project Gutenberg (through Gutendex, its catalog as JSON: popular
// books, shelves, a search), Standard Ebooks (its newest releases: the one
// feed it serves without a Patrons Circle login), any OPDS catalog the scene's
// `catalogs` field lists (a Calibre library, COPS, Kavita, a public feed), and
// a book's own address. A feed is read with frameos.useFetch where the
// runtime has it (the frame draws what it has while it waits), else at once.
//
// A download goes a range of bytes at a time (Range: bytes=a-b) into the
// assets folder, so a book bigger than the frame's memory comes in too, and
// tries the next address it has when one fails before any byte came:
// Gutenberg's own server, then its mirror.

import { clean, decode } from './epub'

export const GUTENDEX = 'https://gutendex.com/books/'
export const SE_FEED = 'https://standardebooks.org/feeds/atom/new-releases'

// Gutenberg's shelves, as Gutendex topics (a word its subjects and bookshelves hold).
export const SHELVES = [
  { label: 'Most popular', topic: '' },
  { label: 'Adventure', topic: 'adventure' },
  { label: 'Science fiction', topic: 'science fiction' },
  { label: 'Mystery and detectives', topic: 'detective' },
  { label: 'Fantasy', topic: 'fantasy' },
  { label: 'Horror and gothic', topic: 'horror' },
  { label: 'Romance', topic: 'love stories' },
  { label: 'Humour', topic: 'humor' },
  { label: "Children's books", topic: 'children' },
  { label: 'Fairy tales', topic: 'fairy tales' },
  { label: 'Short stories', topic: 'short stories' },
  { label: 'Poetry', topic: 'poetry' },
  { label: 'Drama', topic: 'drama' },
  { label: 'Philosophy', topic: 'philosophy' },
  { label: 'History', topic: 'history' },
  { label: 'Travel', topic: 'travel' },
]

// The catalogs field: one a line, "Name | https://…" or just the address.
// Lines starting with # are left out. A user and password go in the address
// (https://me:secret@calibre.local/opds) and are sent as a Basic login.
export function feedsOf(text) {
  const feeds = []
  for (const raw of String(text || '').split('\n')) {
    const line = raw.trim()
    if (!line || line.startsWith('#')) continue
    const bar = line.lastIndexOf('|')
    const name = bar > 0 ? line.slice(0, bar).trim() : ''
    const url = (bar > 0 ? line.slice(bar + 1) : line).trim()
    if (!/^https?:\/\//i.test(url)) continue
    feeds.push({ name: name || hostOf(url), url })
  }
  return feeds
}

export function hostOf(url) {
  const m = /^[a-z]+:\/\/(?:[^@/]*@)?([^/:?#]+)/i.exec(String(url || ''))
  return m ? m[1] : String(url || '')
}

// ---- Asking for a feed ------------------------------------------------------------

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
function base64(text) {
  const bytes = unescape(encodeURIComponent(text))
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes.charCodeAt(i) << 16) | ((bytes.charCodeAt(i + 1) || 0) << 8) | (bytes.charCodeAt(i + 2) || 0)
    out += B64[(n >> 18) & 63] + B64[(n >> 12) & 63] + (i + 1 < bytes.length ? B64[(n >> 6) & 63] : '=') + (i + 2 < bytes.length ? B64[n & 63] : '=')
  }
  return out
}

// An address without its login, and the headers that send it.
export function request(url) {
  const m = /^([a-z]+:\/\/)([^@/]*)@(.*)$/i.exec(url)
  if (!m) return { url, headers: {} }
  let login = m[2]
  try {
    login = decodeURIComponent(login)
  } catch (e) {}
  return { url: m[1] + m[3], headers: { Authorization: `Basic ${base64(login)}` } }
}

const STATUS_WORDS = {
  401: 'a login is needed',
  403: 'not allowed',
  404: 'not found',
  429: 'too many requests, try later',
  500: 'server error',
  502: 'bad gateway',
  503: 'unavailable, try later',
  504: 'gateway timeout',
}
export const answered = (status) => `The server answered ${status}${STATUS_WORDS[status] ? ` (${STATUS_WORDS[status]})` : ''}`

// A feed: { data, error, loading }. data is the parsed JSON, or the text.
export function load(url, asText) {
  const { url: bare, headers } = request(url)
  const init = { headers, maxAge: 3600, timeoutMs: 30000 }
  if (asText) init.as = 'text'
  if (typeof frameos.useFetch === 'function') {
    const r = frameos.useFetch(bare, init)
    if (r.loading && r.data === undefined) return { loading: true }
    if (r.error && r.data === undefined) return { error: plain(r.error) }
    if (r.status && (r.status < 200 || r.status >= 300)) return { error: answered(r.status) }
    return { data: r.data, loading: !!r.loading }
  }
  const res = frameos.httpRequest(bare, { headers, timeoutMs: 30000 })
  if (!res || res.error || !res.status) return { error: plain(res && res.error) }
  if (res.status < 200 || res.status >= 300) return { error: answered(res.status) }
  if (asText) return { data: res.body || '' }
  try {
    return { data: JSON.parse(res.body || 'null') }
  } catch (e) {
    return { error: 'The answer was not what a catalog sends.' }
  }
}

export function plain(error) {
  const text = String(error || 'no answer')
  if (/Local network access is off/.test(text)) return text
  if (/timed? ?out|timeout/i.test(text)) return 'The server took too long to answer.'
  return text.length > 140 ? text.slice(0, 137) + '...' : text
}

// ---- Gutenberg, through Gutendex -------------------------------------------------

export function gutendexUrl({ topic, search, languages, page }) {
  const q = ['sort=popular']
  if (languages) q.push(`languages=${encodeURIComponent(languages)}`)
  if (topic) q.push(`topic=${encodeURIComponent(topic)}`)
  if (search) q.push(`search=${encodeURIComponent(search)}`)
  if (page > 1) q.push(`page=${page}`)
  return `${GUTENDEX}?${q.join('&')}`
}

// "Austen, Jane" -> "Jane Austen".
export function personName(name) {
  const m = /^([^,]+),\s*([^,(]+?)\s*(\(.*\))?$/.exec(String(name || '').trim())
  return m ? `${m[2]} ${m[1]}`.trim() : String(name || '').trim()
}

// A Gutendex page as entries: what a list row and a book's page show, and
// where the book downloads from.
export function fromGutendex(json) {
  const out = { entries: [], count: 0, next: false }
  if (!json || !Array.isArray(json.results)) return out
  out.count = json.count || json.results.length
  out.next = !!json.next
  for (const r of json.results) {
    if (!r || typeof r.id !== 'number') continue
    const formats = r.formats || {}
    if (!Object.keys(formats).some((type) => type.startsWith('application/epub'))) continue
    const id = r.id
    const summary = Array.isArray(r.summaries) && r.summaries[0] ? String(r.summaries[0]).replace(/\s*\(This is an automatically generated summary\.\)\s*$/, '') : ''
    out.entries.push({
      id: `pg${id}`,
      title: String(r.title || 'Untitled').replace(/\s+/g, ' ').trim(),
      author: (r.authors || []).map((a) => personName(a.name)).join(', '),
      summary,
      cover: formats['image/jpeg'] || '',
      language: (r.languages || []).join(', '),
      subjects: (r.bookshelves || []).map((s) => String(s).replace(/^Category:\s*/, '')).slice(0, 4),
      downloads: r.download_count || 0,
      source: 'Project Gutenberg',
      urls: [
        `https://www.gutenberg.org/cache/epub/${id}/pg${id}-images-3.epub`,
        `https://gutenberg.pglaf.org/cache/epub/${id}/pg${id}-images-3.epub`,
        // Without its pictures: what a frame with little memory takes when the
        // book with them is very big.
        `https://www.gutenberg.org/cache/epub/${id}/pg${id}.epub`,
        `https://gutenberg.pglaf.org/cache/epub/${id}/pg${id}.epub`,
      ],
      lighter: 2,
    })
  }
  return out
}

// ---- Atom and OPDS ------------------------------------------------------------------

// An address in a feed, against the feed's own.
export function absolute(href, base) {
  const h = decode(String(href || '').trim())
  if (!h) return ''
  if (/^[a-z][a-z0-9+.-]*:/i.test(h)) return h
  const m = /^([a-z]+:\/\/[^/]+)(\/[^?#]*)?/i.exec(base || '')
  if (!m) return h
  if (h.startsWith('//')) return base.slice(0, base.indexOf(':') + 1) + h
  if (h.startsWith('?')) return base.split(/[?#]/)[0] + h
  if (h.startsWith('#')) return base.split('#')[0] + h
  if (h.startsWith('/')) return m[1] + h
  const dir = (m[2] || '/').replace(/[^/]*$/, '')
  const parts = (dir + h.split(/[?#]/)[0]).split('/')
  const out = []
  for (const part of parts) {
    if (part === '..') out.length > 1 && out.pop()
    else if (part !== '.') out.push(part)
  }
  const rest = h.slice(h.split(/[?#]/)[0].length)
  return m[1] + out.join('/').replace(/^\/*/, '/') + rest
}

const tagText = (xml, tag) => {
  const m = new RegExp(`<(?:[\\w-]+:)?${tag}\\b[^>]*>([\\s\\S]*?)</(?:[\\w-]+:)?${tag}>`, 'i').exec(xml)
  return m ? clean(m[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')) : ''
}
const attr = (tag, name) => {
  const m = new RegExp(`\\s${name}\\s*=\\s*("([^"]*)"|'([^']*)')`, 'i').exec(tag)
  return m ? decode(m[2] !== undefined ? m[2] : m[3]) : ''
}

// An Atom feed, OPDS or not: its title, its entries (books that download as
// EPUB, and catalogs within it), the next page and a search.
export function parseAtom(xml, base) {
  const text = String(xml || '')
  const first = text.search(/<entry\b/i)
  const head = first >= 0 ? text.slice(0, first) : text
  const feed = { title: tagText(head, 'title'), entries: [], next: '', search: '', searchDoc: '' }
  for (const link of head.match(/<link\b[^>]*>/gi) || []) {
    const rel = attr(link, 'rel')
    const type = attr(link, 'type')
    const href = absolute(attr(link, 'href'), base)
    if (rel === 'next') feed.next = href
    if (rel === 'search') {
      if (href.includes('{searchTerms}')) feed.search = href
      else if (/opensearch/i.test(type)) feed.searchDoc = href
    }
  }
  for (const m of text.match(/<entry\b[\s\S]*?<\/entry>/gi) || []) {
    const entry = {
      id: tagText(m, 'id') || '',
      title: tagText(m, 'title') || 'Untitled',
      author: [],
      summary: '',
      cover: '',
      urls: [],
      size: 0,
      nav: '',
      language: tagText(m, 'language'),
      source: feed.title,
    }
    for (const a of m.match(/<author\b[\s\S]*?<\/author>/gi) || []) {
      const name = tagText(a, 'name')
      if (name) entry.author.push(name)
    }
    entry.author = entry.author.join(', ')
    // The longer of the two: Standard Ebooks' summary is a line, its content the blurb.
    const summary = tagText(m, 'summary')
    const content = clean(decode(tagText(m, 'content')))
    entry.summary = content.length > summary.length ? content : summary
    let thumb = ''
    let image = ''
    for (const link of m.match(/<link\b[^>]*>/gi) || []) {
      const rel = attr(link, 'rel')
      const type = attr(link, 'type').toLowerCase()
      const href = absolute(attr(link, 'href'), base)
      if (!href) continue
      if (/image\/thumbnail|cover-image-thumbnail/.test(rel)) thumb = thumb || href
      else if (/opds-spec\.org\/image$|cover-image/.test(rel)) image = image || href
      else if ((/opds-spec\.org\/acquisition/.test(rel) || rel === 'enclosure') && type.startsWith('application/epub+zip')) {
        entry.urls.push(href)
        entry.size = entry.size || Number(attr(link, 'length')) || 0
      } else if (type.includes('application/atom+xml') && rel !== 'alternate' && rel !== 'self' && !/acquisition/.test(rel)) {
        entry.nav = entry.nav || href
      }
    }
    const media = /<media:thumbnail\b[^>]*>/i.exec(m)
    entry.cover = thumb || (media ? absolute(attr(media[0], 'url'), base) : '') || image
    if (entry.urls.length || entry.nav) feed.entries.push(entry)
  }
  return feed
}

// An OpenSearch description's Atom template.
export function searchTemplate(xml, base) {
  for (const url of String(xml || '').match(/<Url\b[^>]*>/gi) || []) {
    const type = attr(url, 'type')
    if (/atom\+xml/i.test(type)) return absolute(attr(url, 'template'), base)
  }
  return ''
}

// ---- Downloading ----------------------------------------------------------------------

// A file name for a book, from its author and title.
export function bookFile(entry) {
  const name = `${entry.author ? entry.author.split(',')[0].trim() + ' - ' : ''}${entry.title}`
    .replace(/[\/\\:*?"<>|]/g, ' ')
    .replace(/[^\p{L}\p{N} ._()+,;=@'&!-]/gu, '')
    .replace(/\s+/g, ' ')
    .replace(/^[\s.]+/, '')
    .trim()
    .slice(0, 90)
  return `${name || 'Book'}.epub`
}

export function base64Bytes(b64) {
  const s = String(b64 || '')
  if (!s.length) return 0
  const padding = s.endsWith('==') ? 2 : s.endsWith('=') ? 1 : 0
  return Math.floor((s.length * 3) / 4) - padding
}

// The file's whole size as the answer says it: content-range on a 206,
// content-length on a 200 (FrameOS 2026.11.12+ hands headers over).
function totalOf(res) {
  const headers = res && res.headers
  if (!headers || typeof headers !== 'object') return null
  if (res.status === 206 || res.status === 416) {
    const m = /\/\s*(\d+)\s*$/.exec(String(headers['content-range'] || ''))
    return m ? Number(m[1]) : null
  }
  if (res.status === 200 && headers['content-length'] !== undefined && !headers['content-encoding']) {
    const n = Number(headers['content-length'])
    return Number.isFinite(n) && n >= 0 ? n : null
  }
  return null
}

// A new download: the entry's addresses tried in turn, into `path`.
export function startDownload(entry, path, now) {
  return { title: entry.title, author: entry.author || '', urls: entry.urls.slice(), lighter: entry.lighter || 0, u: 0, path, offset: 0, total: null, retries: 0, at: now, state: 'busy', error: '' }
}

// One chunk of a download, fetched and written. `limits` = { chunk, maxBytes,
// lightAbove }. Returns the job as it is now: state 'busy', 'done' or 'failed'.
export function stepDownload(job, limits) {
  const fail = (error) => {
    if (job.offset > 0) frameos.deleteAsset(job.path)
    return { ...job, state: 'failed', error }
  }
  // The next address, when this one failed before a byte came.
  const nextUrl = (error) => {
    if (job.offset === 0 && job.u + 1 < job.urls.length) return { ...job, u: job.u + 1, retries: 0, total: null, lastError: error }
    return null
  }
  const retry = (error) => {
    const retries = (job.retries || 0) + 1
    if (retries >= 3) return nextUrl(error) || fail(plain(error))
    return { ...job, retries, lastError: plain(error) }
  }
  const url = job.urls[job.u]
  const last = typeof job.total === 'number' ? Math.min(job.offset + limits.chunk, job.total) - 1 : job.offset + limits.chunk - 1
  const res = frameos.httpRequest(url, { headers: { Range: `bytes=${job.offset}-${last}` }, base64: true, timeoutMs: 30000 })
  if (!res || res.error || !res.status) {
    if (/exceeded \d+ bytes/.test(String(res && res.error))) return nextUrl('too big') || fail('This server sends only whole books, and this one is bigger than the frame takes at once.')
    return retry(res && res.error)
  }
  const write = (b64) => (job.offset === 0 ? frameos.writeAsset(job.path, b64) : frameos.appendAsset(job.path, b64))
  const CANNOT = 'The frame could not write the book: it needs room on its disk, and the scene permission to write the assets folder.'
  if (res.status === 206 || res.status === 200) {
    const total = res.status === 206 ? (job.total ?? totalOf(res)) : null
    // A very big book with its pictures, on a frame with little memory: the
    // one without them, when there is one.
    if (job.offset === 0 && total && limits.lightAbove && total > limits.lightAbove && job.lighter && job.u < job.lighter) {
      return { ...job, u: job.lighter, total: null, retries: 0 }
    }
    if (total !== null && total > limits.maxBytes) return fail(`The book is ${Math.round(total / 1048576)} MB, more than this frame keeps.`)
    const b64 = res.bodyBase64 || ''
    const bytes = base64Bytes(b64)
    if (res.status === 200) {
      // The whole book at once: the server ignored the range.
      if (bytes > limits.maxBytes) return fail('The book is bigger than this frame keeps.')
      if (bytes < 4 || !/^UEsD/.test(b64)) return nextUrl('not a book') || fail('The address did not answer with an EPUB book.')
      if (!frameos.writeAsset(job.path, b64)) return fail(CANNOT)
      return { ...job, offset: bytes, total: bytes, state: 'done' }
    }
    if (job.offset === 0 && !/^UEsD/.test(b64)) return nextUrl('not a book') || fail('The address did not answer with an EPUB book.')
    if (bytes > 0 && !write(b64)) return fail(CANNOT)
    const offset = job.offset + bytes
    const done = total !== null ? offset >= total || bytes === 0 : bytes < limits.chunk
    return { ...job, offset, total, retries: 0, lastError: '', state: done ? 'done' : 'busy' }
  }
  if (res.status === 416 && job.offset > 0) return { ...job, state: 'done' }
  return nextUrl(answered(res.status)) || fail(answered(res.status))
}

