import { feedsOf, request, absolute, parseAtom, searchTemplate, fromGutendex, personName, bookFile, gutendexUrl, stepDownload, startDownload } from './catalog'
import { toClippings, toMarkdown, mergeBackup, bookmarkOn, textBetween, putMark, dropMark, fileName } from './marks'
import { countTurn, streak, summary } from './stats'
import { prefsOf, layoutPage, justified, xOf, DEFAULT_SIZE } from './pages'
import { parseChapter } from './epub'
import { duration } from './ui'

describe('catalogs', () => {
  it('reads the catalogs field: names, addresses, comments', () => {
    expect(feedsOf('# a comment\nCalibre | http://me:pw@calibre.local:8080/opds\nhttps://example.org/feed.xml\nnot an address')).toEqual([
      { name: 'Calibre', url: 'http://me:pw@calibre.local:8080/opds' },
      { name: 'example.org', url: 'https://example.org/feed.xml' },
    ])
  })
  it('sends a login in an address as Basic', () => {
    expect(request('http://me:pw@calibre.local:8080/opds')).toEqual({ url: 'http://calibre.local:8080/opds', headers: { Authorization: 'Basic bWU6cHc=' } })
    expect(request('https://example.org/x').headers).toEqual({})
  })
  it('resolves a feed address against the feed', () => {
    expect(absolute('/opds/new', 'https://books.example/opds')).toBe('https://books.example/opds/new')
    expect(absolute('../books/9.epub', 'https://books.example/opds/new')).toBe('https://books.example/books/9.epub')
    expect(absolute('next?page=2', 'https://books.example/opds/new')).toBe('https://books.example/opds/next?page=2')
    expect(absolute('https://elsewhere.org/a', 'https://books.example/opds')).toBe('https://elsewhere.org/a')
    expect(absolute('a&amp;b', 'https://books.example/x/')).toBe('https://books.example/x/a&b')
  })
  it('reads an OPDS feed: books that download as EPUB, catalogs in it, the next page and a search', () => {
    const feed = parseAtom(
