      <entry><title>Book &amp; More</title><author><name>A. Writer</name></author><author><name>B. Writer</name></author>
        <summary>Short.</summary><link rel="http://opds-spec.org/image/thumbnail" href="/t/1.jpg"/>
        <link rel="http://opds-spec.org/acquisition/open-access" type="application/epub+zip" href="/b/1.epub" length="1234"/>
        <link rel="http://opds-spec.org/acquisition" type="application/pdf" href="/b/1.pdf"/></entry>
      <entry><title>Only PDF</title><link rel="http://opds-spec.org/acquisition" type="application/pdf" href="/b/2.pdf"/></entry>
      <entry><title>Poetry</title><link rel="subsection" type="application/atom+xml;profile=opds-catalog" href="/poetry"/></entry></feed>`,
      'https://lib.example/opds',
    )
    expect(feed.title).toBe('Shelf')
    expect(feed.next).toBe('https://lib.example/opds?page=2')
    expect(feed.search).toBe('https://lib.example/search?q={searchTerms}')
    expect(feed.entries.length).toBe(2)
    expect(feed.entries[0]).toMatchObject({ title: 'Book & More', author: 'A. Writer, B. Writer', summary: 'Short.', cover: 'https://lib.example/t/1.jpg', urls: ['https://lib.example/b/1.epub'], size: 1234 })
    expect(feed.entries[1]).toMatchObject({ title: 'Poetry', nav: 'https://lib.example/poetry' })
  })
  it("reads Standard Ebooks' Atom feed: enclosures and media thumbnails", () => {
    const feed = parseAtom(
      `<feed><title>Standard Ebooks - Newest Ebooks</title><entry><title>Confessions of Zeno</title><author><name>Italo Svevo</name></author>
      <summary type="text">To quit smoking, a man writes his memoirs.</summary>
      <link href="https://standardebooks.org/x.epub?source=feed" length="875588" rel="enclosure" title="Recommended compatible epub" type="application/epub+zip"/>
      <link href="https://standardebooks.org/x.kepub.epub?source=feed" rel="enclosure" type="application/kepub+zip"/>
      <media:thumbnail height="525" url="https://standardebooks.org/cover-thumbnail.jpg" width="350"/></entry></feed>`,
      'https://standardebooks.org/feeds/atom/new-releases',
    )
    expect(feed.entries[0]).toMatchObject({ author: 'Italo Svevo', urls: ['https://standardebooks.org/x.epub?source=feed'], cover: 'https://standardebooks.org/cover-thumbnail.jpg', size: 875588 })
  })
  it("reads an OpenSearch description's Atom template", () => {
    expect(searchTemplate('<OpenSearchDescription><Url type="text/html" template="/h?q={searchTerms}"/><Url type="application/atom+xml" template="/opds/search/{searchTerms}"/></OpenSearchDescription>', 'https://c.example/opds')).toBe(
      'https://c.example/opds/search/{searchTerms}',
    )
  })
  it("reads Gutendex: names first-name first, Gutenberg's server then its mirror, no book without an EPUB", () => {
    const page = fromGutendex({
      count: 2,
      next: 'https://gutendex.com/books/?page=2',
      results: [
        { id: 11, title: "Alice's Adventures in Wonderland", authors: [{ name: 'Carroll, Lewis' }], summaries: ['A girl falls. (This is an automatically generated summary.)'], bookshelves: ['Category: Novels'], languages: ['en'], formats: { 'application/epub+zip': 'x', 'image/jpeg': 'c.jpg' }, download_count: 9000 },
        { id: 12, title: 'Text', authors: [], formats: { 'text/plain': 'y' } },
      ],
    })
    expect(page.next).toBe(true)
    expect(page.entries.length).toBe(1)
    expect(page.entries[0]).toMatchObject({ title: "Alice's Adventures in Wonderland", author: 'Lewis Carroll', summary: 'A girl falls.', cover: 'c.jpg', subjects: ['Novels'] })
    expect(page.entries[0].urls.slice(0, 2)).toEqual(['https://www.gutenberg.org/cache/epub/11/pg11-images-3.epub', 'https://gutenberg.pglaf.org/cache/epub/11/pg11-images-3.epub'])
    expect(personName('Shelley, Mary Wollstonecraft (1797-1851)')).toBe('Mary Wollstonecraft Shelley')
    expect(gutendexUrl({ topic: 'science fiction', languages: 'en,fr', page: 2 })).toBe('https://gutendex.com/books/?sort=popular&languages=en%2Cfr&topic=science%20fiction&page=2')
  })
  it('names a downloaded book after its author and title, as a file name', () => {
    expect(bookFile({ title: 'Frankenstein; Or, The Modern Prometheus', author: 'Mary Shelley' })).toBe('Mary Shelley - Frankenstein; Or, The Modern Prometheus.epub')
    expect(bookFile({ title: 'A/B: "C"?', author: '' })).toBe('A B C.epub')
  })
  it('downloads a range at a time, and tries the next address when one fails before any byte', () => {
    const book = 'UEsDBBQAAAAIAAAA' + 'A'.repeat(40)
    const asked = []
    mock.httpRequest((url, options) => {
      asked.push(url + ' ' + options.headers.Range)
      if (url.includes('down')) return { status: 503 }
      return { status: 206, bodyBase64: book, headers: { 'content-range': 'bytes 0-41/42' } }
    })
    mock.writeAsset(() => true)
    let job = startDownload({ title: 'T', urls: ['https://down.example/b.epub', 'https://up.example/b.epub'] }, 'Books/T.epub', 0)
    job = stepDownload(job, { chunk: 1024, maxBytes: 1 << 20 })
    expect(job.u).toBe(1)
    job = stepDownload(job, { chunk: 1024, maxBytes: 1 << 20 })
    expect(job.state).toBe('done')
    expect(asked).toEqual(['https://down.example/b.epub bytes=0-1023', 'https://up.example/b.epub bytes=0-1023'])
  })
})

describe('marks', () => {
  const book = { path: 'assets:Books/a.epub', title: 'A Book', author: 'An Author' }
  const marks = {}
  putMark(marks, book, { id: 'h1', k: 'h', s: 2, p: 0, b: 3, c: 0, b2: 3, c2: 10, t: 'Ten words.', n: 'Mine', at: Date.UTC(2026, 10, 28, 9, 5, 7), f: 0.25, ch: 'Two' })
  putMark(marks, book, { id: 'b1', k: 'b', s: 1, p: 0, b: 0, c: 0, t: 'The page', at: Date.UTC(2026, 10, 27, 9, 5, 7), f: 0.1, ch: 'One' })

  it('keeps a book’s marks in its order', () => {
    expect(marks[book.path].list.map((m) => m.id)).toEqual(['b1', 'h1'])
  })
  it('writes a Kindle My Clippings.txt: a highlight and its note, a bookmark', () => {
    const text = toClippings(marks)
    const records = text.split('==========\n')
    expect(records.length).toBe(4)
    expect(records[0]).toMatch(/^A Book \(An Author\)\n- Your Bookmark at location 1000 \| Added on /)
    expect(records[1]).toMatch(/^A Book \(An Author\)\n- Your Highlight at location 2500 \| Added on .*\n\nTen words\.\n$/)
    expect(records[2]).toMatch(/- Your Note at location 2500 .*\n\nMine\n$/)
  })
  it('writes Markdown under the chapters', () => {
    const md = toMarkdown(marks[book.path], Date.UTC(2026, 10, 28))
    expect(md).toContain('# A Book')
    expect(md).toContain('## One\n\n- Bookmark at 10%')
    expect(md).toContain('## Two\n\n> Ten words.\n\n**Note:** Mine')
  })
  it('merges a backup: new marks, newer places, the days', () => {
    const backup = JSON.stringify({
      format: 'frameos-books',
      marks: { [book.path]: { title: 'A Book', list: [{ id: 'h2', k: 'h', s: 5, b: 0, c: 0, at: 5 }, { id: 'b1', k: 'b', s: 1, b: 0, c: 0, at: 1 }] } },
      books: { [book.path]: { s: 5, t: 99 }, 'assets:other.epub': { s: 1, t: 1 } },
      days: { '2026-11-01': 60 },
    })
    const spot = { books: { [book.path]: { s: 2, t: 100 } }, days: { '2026-11-01': 30 } }
    const r = mergeBackup(backup, marks, spot)
    expect(r).toEqual({ added: 1, places: 1 })
    expect(spot.books[book.path].s).toBe(2)
    expect(spot.days['2026-11-01']).toBe(60)
    expect(mergeBackup('{}', marks, spot).error).toContain('not a FrameOS books backup')
  })
  it('finds the bookmark on a spread, and drops a mark', () => {
    const list = marks[book.path].list
    expect(bookmarkOn(list, { s: 1, p: 0, b: 0, c: 0 }, [4, 0])?.id).toBe('b1')
    expect(bookmarkOn(list, { s: 1, p: 0, b: 0, c: 1 }, [4, 0])).toBe(null)
    dropMark(marks, book.path, 'h2')
    expect(marks[book.path].list.some((m) => m.id === 'h2')).toBe(false)
  })
  it('reads the text between two places, a paragraph a line', () => {
    expect(textBetween([{ t: 'One two three.' }, { t: '' }, { t: 'Four five.' }], 0, 4, 2, 4)).toBe('two three.\nFour')
  })
  it('makes a title a file name', () => {
    expect(fileName('Crime/Punishment: "A Novel"')).toBe('Crime Punishment A Novel')
  })
})

describe('reading stats', () => {
  it('counts the time between turns, at most four minutes a page, and the pace', () => {
    const spot = {}
    const t0 = Date.UTC(2026, 10, 28, 10, 0, 0)
    countTurn(spot, 'k', 0, t0, false)
    expect(countTurn(spot, 'k', 1500, t0 + 60000, true)).toBe(60)
    expect(countTurn(spot, 'k', 1500, t0 + 60000 + 3600000, true)).toBe(240)
    expect(spot.books.k).toMatchObject({ secs: 300, pages: 2 })
    expect(spot.speed).toBe(25)
    expect(spot.totals).toEqual({ secs: 300, pages: 2 })
  })
  it('a streak is the days in a row, today or up to yesterday', () => {
    const now = new Date(2026, 10, 28, 12).getTime()
    expect(streak({ '2026-11-26': 5, '2026-11-27': 9 }, now)).toBe(2)
    expect(streak({ '2026-11-26': 5, '2026-11-28': 9 }, now)).toBe(1)
    const s = summary({ days: { '2026-11-28': 120 }, books: { a: { done: 1 }, b: { f: 0.3 } } }, now)
    expect(s).toMatchObject({ today: 120, weekSecs: 120, finished: 1, reading: 1 })
    expect(duration(3720)).toBe('1 h 2 min')
  })
})

describe('pages', () => {
  it('keeps the text size of a spot from before the reading settings', () => {
    expect(prefsOf({ size: 4 }).size).toBe(DEFAULT_SIZE)
    expect(prefsOf({ prefs: { size: 2, justify: true, theme: 'sepia' } })).toMatchObject({ size: 2, justify: true, theme: 'sepia', spacing: 1, margin: 1, status: 'full' })
  })
  it('lays out lines that say which characters they show; justified lines fill the width', () => {
    const blocks = parseChapter('<body><p>The quick brown fox jumps over the lazy dog, again and again and again until the line runs out.</p></body>', '')
    const g = { fs: 20, lh: 28, w: 300, h: 600, sizeOf: () => null }
    const { lines, next } = layoutPage(blocks, [0, 0], g)
    expect(next).toBe(null)
    expect(lines.length > 1).toBe(true)
    expect(lines[0].c).toBe(0)
    expect(blocks[0].t.slice(lines[1].c, lines[1].e)).toBe(lines[1].t)
    expect(lines[0].j).toBe(true)
    expect(lines[lines.length - 1].j).toBe(false)
    const words = justified(lines[0])
    const last = words[words.length - 1]
    expect(Math.round(last.x + last.w)).toBe(Math.round(lines[0].w))
    expect(Math.round(xOf(lines[0], lines[0].e, true))).toBe(Math.round(lines[0].w))
  })
})
